import streamlit as st
import pandas as pd
import numpy as np
def generate_alpha_features(df, date_id_col="date_id", returns_col="returns_past_5d"):
    """Generates market-neutral alpha features for boosting models."""
    df = df.copy()
    if returns_col not in df.columns:
        return df
    if date_id_col in df.columns:
        market_mean = df.groupby(date_id_col)[returns_col].transform("mean")
        df["alpha_rel_strength"] = df[returns_col] - market_mean
        market_std = df.groupby(date_id_col)[returns_col].transform("std")
        df["alpha_z_score"] = (df[returns_col] - market_mean) / (market_std + 1e-8)
    else:
        market_mean = df[returns_col].mean()
        market_std = df[returns_col].std()
        df["alpha_rel_strength"] = df[returns_col] - market_mean
        df["alpha_z_score"] = (df[returns_col] - market_mean) / (market_std + 1e-8)
    return df

def rf_kill_test(X, y):
    """Stress-tests RF to expose overfitting via high min_samples_leaf."""
    # pandas already imported globally
    from sklearn.ensemble import RandomForestRegressor
    from sklearn.metrics import r2_score
    from sklearn.model_selection import TimeSeriesSplit
    # 20-day purging gap to prevent overlap leakage
    tscv = TimeSeriesSplit(n_splits=3, max_train_size=None)
    scores = []
    for train_idx, val_idx in tscv.split(X):
        X_t, X_v = X.iloc[train_idx], X.iloc[val_idx]
        y_t, y_v = y.iloc[train_idx], y.iloc[val_idx]
        rf = RandomForestRegressor(n_estimators=50, max_depth=5, min_samples_leaf=100, n_jobs=-1, random_state=42)
        rf.fit(X_t, y_t)
        scores.append(r2_score(y_v, rf.predict(X_v)))
    rf.fit(X, y)
    importances = pd.Series(rf.feature_importances_, index=X.columns)
    top_feat = importances.sort_values(ascending=False).head(1)
    return {"leaf_test_r2": float(np.mean(scores)), "top_feature": top_feat.index[0], "top_importance": float(top_feat.values[0]), "is_overfitting": np.mean(scores) < 0.01, "has_dominance": top_feat.values[0] > 0.40}

# ════════════════════════════════════════════════════════════════════════════
# 🔬 FEATURE SIGNAL QUALITY ANALYSIS - Identify top 5-10 real signals
# ════════════════════════════════════════════════════════════════════════════
def analyze_feature_signals(X_train, y_train, X_test, y_test, top_n=10):
    """Analyze which features provide real (non-fake) predictive signals."""
    import numpy as np
    # pandas already imported globally
    from scipy.stats import spearmanr
    
    results = []
    
    categories = {
        'Momentum': ['momentum', 'mom_', 'return', 'roc', 'M1', 'M2', 'M3', 'M4', 'M5'],
        'Volatility': ['volatility', 'vol_', 'std', 'V1', 'V2', 'V3', 'V4', 'V5', 'V6', 'V7', 'V8', 'V9', 'V10'],
        'Value': ['value', 'ratio', 'pe', 'pb', 'E1', 'E2', 'E3', 'E4', 'E5'],
        'Sentiment': ['sentiment', 'S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10', 'S11', 'S12'],
        'Industry': ['industry', 'sector', 'I1', 'I2', 'I3', 'I4', 'I5'],
        'Technical': ['rsi', 'macd', 'ema', 'sma', 'D1', 'D2', 'D3', 'D4', 'D5'],
        'Other': []
    }
    
    def categorize_feature(name):
        name_lower = name.lower()
        for cat, keywords in categories.items():
            if any(kw.lower() in name_lower for kw in keywords):
                return cat
        return 'Other'
    
    for col in X_train.columns:
        try:
            train_vals = X_train[col].fillna(0).values
            train_ic, _ = spearmanr(train_vals, y_train.values if hasattr(y_train, 'values') else y_train)
            test_vals = X_test[col].fillna(0).values
            test_ic, _ = spearmanr(test_vals, y_test.values if hasattr(y_test, 'values') else y_test)
            ic_stability = 1.0 - abs(train_ic - test_ic) if not np.isnan(train_ic) and not np.isnan(test_ic) else 0.0
            signal_score = abs(test_ic) * 0.7 + ic_stability * 0.3 if not np.isnan(test_ic) else 0.0
            results.append({
                'feature': col,
                'category': categorize_feature(col),
                'train_ic': train_ic if not np.isnan(train_ic) else 0.0,
                'test_ic': test_ic if not np.isnan(test_ic) else 0.0,
                'ic_stability': ic_stability,
                'signal_score': signal_score
            })
        except Exception:
            pass
    
    df = pd.DataFrame(results)
    df = df.sort_values('signal_score', ascending=False)
    return df.head(top_n), df




