def safe_install(package):
    """Install a package if not already installed"""
    try:
        importlib.import_module(package.split("==")[0])
        print(f"✅ {package.split('==')[0]} already installed")
    except ImportError:
        print(f"📦 Installing {package}")
        subprocess.check_call([sys.executable, "-m", "pip", "install", package])

def install_torchvision():
    import torch
    torch_version = torch.__version__.split("+")[0]  # e.g., '2.8.0'
    torch_to_tv = {
        "2.0.0": "0.15.1",
        "2.0.1": "0.15.2",
        "2.1.0": "0.16.1",
        "2.1.1": "0.16.2",
        "2.2.0": "0.17.0",
        "2.2.1": "0.17.1",
        "2.3.0": "0.18.0",
        "2.3.1": "0.18.1",
        "2.4.0": "0.19.0",
        "2.8.0": "0.23.0",   # ✅ Added explicit mapping for PyTorch 2.8.0
    }
    tv_version = torch_to_tv.get(torch_version, None)

    if tv_version is None:
        print(f"⚠️ No torchvision mapping for torch=={torch_version}, installing latest torchvision")
        safe_install("torchvision --upgrade")
    else:
        safe_install(f"torchvision=={tv_version}")

