# --- UNIFIED KAGGLE CREDENTIAL MANAGEMENT ---
def ensure_kaggle_credentials() -> bool:
    """
    Unified platform credential management - ensures credentials are available from any source
    and creates ~/.kaggle/kaggle.json if needed. Single source of truth for all platform operations.
    
    Source precedence: session_state -> environment -> existing file
    Returns: True if credentials successfully set up, False otherwise
    """
    try:
        import os
        from pathlib import Path
        import json
        
        # Check session state first (from UI input)
        kaggle_username = st.session_state.get("kaggle_username")
        kaggle_key = st.session_state.get("kaggle_key") 
        
        # Check environment variables second
        if not kaggle_username or not kaggle_key:
            kaggle_username = os.environ.get("KAGGLE_USERNAME")
            kaggle_key = os.environ.get("KAGGLE_KEY")
        
        # Check existing file third
        kaggle_dir = Path.home() / ".kaggle"
        kaggle_file = kaggle_dir / "kaggle.json"
        
        if not kaggle_username or not kaggle_key:
            if kaggle_file.exists():
                try:
                    with open(kaggle_file, 'r') as f:
                        creds = json.load(f)
                    kaggle_username = creds.get("username")
                    kaggle_key = creds.get("key")
                except:
                    pass
        
        # If we still don't have credentials, return False
        if not kaggle_username or not kaggle_key:
            return False
        
        # Create kaggle directory and file
        kaggle_dir.mkdir(mode=0o700, exist_ok=True)
        
        # Write credentials to file
        credentials = {
            "username": kaggle_username,
            "key": kaggle_key
        }
        
        with open(kaggle_file, 'w') as f:
            json.dump(credentials, f)
        
        # Set secure permissions
        kaggle_file.chmod(0o600)
        
        # Set environment variables for Platform API
        os.environ["KAGGLE_USERNAME"] = kaggle_username
        os.environ["KAGGLE_KEY"] = kaggle_key
        os.environ["KAGGLE_CONFIG_DIR"] = str(kaggle_dir)
        
        return True
        
    except Exception as e:
        st.error(f"Failed to set up Platform credentials: {str(e)}")
        return False

def get_kaggle_api():
    """Get authenticated Platform API client"""
    if not ensure_kaggle_credentials():
        raise RuntimeError("Platform credentials not configured. Please set up your API credentials first.")
    
    try:
        import kaggle
        kaggle.api.authenticate()
        return kaggle.api
    except Exception as e:
        raise RuntimeError(f"Failed to authenticate Platform API: {str(e)}")

def run_kaggle_cli(args: List[str]) -> subprocess.CompletedProcess:
    """Run Platform CLI command with proper credential setup"""
    if not ensure_kaggle_credentials():
        raise RuntimeError("Platform credentials not configured. Please set up your API credentials first.")
    
    try:
        # Ensure kaggle CLI is available
        if not ensure_kaggle_installed():
            raise RuntimeError("Platform CLI not available")
        
        # Set up environment
        env = os.environ.copy()
        env["KAGGLE_CONFIG_DIR"] = str(Path.home() / ".kaggle")
        
        # Run command
        result = subprocess.run(["kaggle"] + args, env=env, check=True, 
                               capture_output=True, text=True)
        return result
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Platform CLI command failed: {e.stderr}")
    except Exception as e:
        raise RuntimeError(f"Failed to run platform CLI: {str(e)}")

def safe_attr(obj, *attrs, default="Unknown"):
    """Safely fetch nested attributes with fallback."""
    for attr in attrs:
        if hasattr(obj, attr):
            return getattr(obj, attr)
    return default


def extract_competition_slug(competition_name_or_url: str) -> str:
    """
    Extract competition slug from Platform URL or return as-is.
    
    Examples:
        "https://www.kaggle.com/competitions/titanic" → "titanic"
        "titanic" → "titanic"
    """
    match = re.search(r"/competitions/([^/?#]+)", competition_name_or_url)
    if match:
        return match.group(1)
    return competition_name_or_url.strip()


def get_competition_info(competition_name_or_url: str) -> dict:
    """
    Retrieve Project info with improved error handling.
    
    Args:
        competition_name_or_url (str): Slug or URL of the competition.
    
    Returns:
        dict: Competition info with standardized structure.
    """
    try:
        import kaggle
        api = kaggle.api
        api.authenticate()
        slug = extract_competition_slug(competition_name_or_url)

        competitions = api.competitions_list(search=slug)
        competition = None

        # Try exact and partial matches
        for comp in competitions:
            if hasattr(comp, "ref") and comp.ref == slug:
                competition = comp
                break
            elif hasattr(comp, "slug") and comp.slug == slug:
                competition = comp
                break
            elif hasattr(comp, "ref") and comp.ref and slug.lower() in comp.ref.lower():
                competition = comp
                break
            elif hasattr(comp, "title") and comp.title and slug.lower() in comp.title.lower():
                competition = comp
                break

        if not competition:
            return {
                "title": f"Project not found: {slug}",
                "ref": slug,
                "description": "Not available",
                "evaluationMetric": "Not available",
                "deadline": "Not available",
                "problem_type": "Unknown",
                "target": "Unknown",
                "totalTeams": "Unknown",
                "category": "Unknown",
                "api_error": False
            }

        # Build structured response with safe attribute access
        return {
            "title": safe_attr(competition, "title"),
            "ref": safe_attr(competition, "ref", default=slug),
            "description": safe_attr(competition, "description", default="Check competition page"),
            "evaluationMetric": safe_attr(
                competition, "evaluationMetric", "evaluationMethod", default="Check competition page"
            ),
            "deadline": safe_attr(competition, "deadline", default="Check competition page"),
            "problem_type": "Unknown",  # requires extra parsing
            "target": "Unknown",        # requires extra parsing
            "totalTeams": safe_attr(competition, "totalTeams", "teamsCount", default="Unknown"),
            "category": safe_attr(competition, "category", default="Unknown"),
            "api_error": False
        }
    
    except Exception as e:
        return {
            "title": f"API Error: {str(e)}",
            "ref": extract_competition_slug(competition_name_or_url),
            "description": "API Error",
            "evaluationMetric": "Unknown",
            "deadline": "Unknown", 
            "problem_type": "Unknown",
            "target": "Unknown",
            "totalTeams": "Unknown",
            "category": "Unknown",
            "api_error": True,
            "error_message": str(e)
        }

