from sklearn.base import BaseEstimator

# ----------------------------
# Auto Hyperparameter Recommendation Functions
# ----------------------------
def recommend_arima_order(y, max_p=5, max_q=5):
    """Statistical analysis-based ARIMA order recommendation using ADF test and PACF/ACF"""
    try:
        from statsmodels.tsa.stattools import adfuller, acf, pacf
        
        # Determine differencing using Augmented Dickey-Fuller test
        d = 0
        result = adfuller(y)
        if result[1] > 0.05:  # p-value > 0.05 means non-stationary
            d = 1  # Apply first differencing
        
        # Use PACF for AR order (p) and ACF for MA order (q)
        p = min(max_p, np.argmax(np.abs(pacf(y, nlags=max_p))) + 1)
        q = min(max_q, np.argmax(np.abs(acf(y, nlags=max_q))) + 1)
        
        return (p, d, q)
    except Exception:
        # Fallback to conservative default
        return (1, 1, 1)

def recommend_hw_seasonality(y):
    """Data-driven Holt-Winters seasonality recommendation"""
    n = len(y)
    if n >= 24:
        return 'add', 12  # Monthly seasonality for sufficient data
    return 'add', max(2, n//4)  # Adaptive seasonality for smaller datasets

def recommend_prophet_seasonality(y):
    """Intelligent Prophet seasonality configuration based on data size"""
    n = len(y)
    yearly = n > 365    # Enable yearly seasonality for data > 1 year
    weekly = n > 30     # Enable weekly seasonality for data > 1 month  
    daily = n > 7       # Enable daily seasonality for data > 1 week
    return yearly, weekly, daily

def recommend_lstm_seq_length(y):
    """Adaptive LSTM sequence length based on data characteristics"""
    n = len(y)
    return min(50, max(5, n//20))  # Smart heuristic: 5% of data length, capped at 50

# ==========================
# Enhanced ARIMA Adapter with Auto Hyperparameters
# ==========================
class ARIMAAdapter(BaseEstimator):
    def __init__(self, order=None):
        self.order = order
        self.model = None
        self.fitted_model = None

    def fit(self, X, y):
        try:
            from statsmodels.tsa.arima.model import ARIMA
        except ImportError:
            raise ImportError("statsmodels is required for ARIMAAdapter")
            
        y_series = np.array(y).astype(float)
        
        # 🧠 AUTO HYPERPARAMETER OPTIMIZATION
        if self.order is None:
            self.order = recommend_arima_order(y_series)
            
        self.model = ARIMA(y_series, order=self.order)
        self.fitted_model = self.model.fit()
        return self

    def predict(self, X):
        if self.fitted_model is None:
            raise ValueError("Model not fitted yet.")
        n_forecast = len(X)
        return self.fitted_model.forecast(steps=n_forecast)

    def get_params(self, deep=True):
        return {"order": self.order}

    def set_params(self, **params):
        for k, v in params.items():
            setattr(self, k, v)
        return self

# ==========================
# Enhanced Holt-Winters Adapter with Auto Hyperparameters
# ==========================
class HoltWintersAdapter(BaseEstimator):
    def __init__(self, seasonal=None, seasonal_periods=None):
        self.seasonal = seasonal
        self.seasonal_periods = seasonal_periods
        self.model = None
        self.fitted_model = None

    def fit(self, X, y):
        try:
            from statsmodels.tsa.holtwinters import ExponentialSmoothing
        except ImportError:
            raise ImportError("statsmodels is required for HoltWintersAdapter")
            
        y_series = np.array(y).astype(float)
        
        # 🧠 AUTO HYPERPARAMETER OPTIMIZATION
        if self.seasonal is None or self.seasonal_periods is None:
            self.seasonal, self.seasonal_periods = recommend_hw_seasonality(y_series)
            
        self.model = ExponentialSmoothing(y_series, seasonal=self.seasonal, seasonal_periods=self.seasonal_periods)
        self.fitted_model = self.model.fit()
        return self

    def predict(self, X):
        if self.fitted_model is None:
            raise ValueError("Model not fitted yet.")
        n_forecast = len(X)
        return self.fitted_model.forecast(n_forecast)

    def get_params(self, deep=True):
        return {
            "seasonal": self.seasonal,
            "seasonal_periods": self.seasonal_periods,
        }

    def set_params(self, **params):
        for k, v in params.items():
            setattr(self, k, v)
        return self


# ==========================
# LightGBM Booster Wrapper (picklable, sklearn-compatible)
# ==========================
class LGBMBoosterWrapper:
    """Sklearn-compatible wrapper for LightGBM Booster (for PBT/Incremental training)"""
    def __init__(self, booster, is_classifier=False):
        self.booster = booster
        self.is_classifier = is_classifier
        self._classes = np.array([0, 1]) if is_classifier else None
        self._is_fitted = True
    
    def fit(self, X, y):
        # No-op - booster is already trained
        return self
    
    def predict(self, X):
        if hasattr(X, 'values'):
            X = X.values
        preds = self.booster.predict(X)
        if self.is_classifier:
            return (preds > 0.5).astype(int)
        return preds
    
    def predict_proba(self, X):
        if hasattr(X, 'values'):
            X = X.values
        preds = self.booster.predict(X)
        return np.column_stack([1 - preds, preds])
    
    def __sklearn_is_fitted__(self):
        return True

# ==========================
# Enhanced Prophet Adapter with Auto Hyperparameters
# ==========================
class ProphetAdapter(BaseEstimator):
    def __init__(self, yearly_seasonality=None, weekly_seasonality=None, daily_seasonality=None):
        self.yearly_seasonality = yearly_seasonality
        self.weekly_seasonality = weekly_seasonality
        self.daily_seasonality = daily_seasonality
        self.model = None
        self.n_train = None

    def fit(self, X, y):
        try:
            from prophet import Prophet
        except ImportError:
            try:
                from fbprophet import Prophet
            except ImportError:
                raise ImportError("prophet is required for ProphetAdapter")
                
        # 🧠 AUTO HYPERPARAMETER OPTIMIZATION
        if self.yearly_seasonality is None or self.weekly_seasonality is None or self.daily_seasonality is None:
            y_series = np.array(y).astype(float)
            self.yearly_seasonality, self.weekly_seasonality, self.daily_seasonality = recommend_prophet_seasonality(y_series)
        
        # Store training set size for prediction
        self.n_train = len(y)
        
        # Create datetime index (one per timestep, starting from a base date)
        dates = pd.date_range(start='2020-01-01', periods=len(y), freq='D')
        
        df = pd.DataFrame({
            'ds': dates,
            'y': np.array(y).astype(float)
        })
        
        self.model = Prophet(
            yearly_seasonality=self.yearly_seasonality,
            weekly_seasonality=self.weekly_seasonality,
            daily_seasonality=self.daily_seasonality,
            interval_width=0.95
        )
        
        # Suppress Prophet warnings
        import logging
        logging.getLogger('prophet').setLevel(logging.WARNING)
        logging.getLogger('cmdstanpy').setLevel(logging.WARNING)
        
        self.model.fit(df)
        return self

    def predict(self, X):
        if self.model is None:
            raise ValueError("Model not fitted yet.")
        
        # Create future dates for predictions
        n_predict = len(X) if hasattr(X, '__len__') else 1
        future_dates = pd.date_range(start='2020-01-01', periods=self.n_train + n_predict, freq='D')
        df_future = pd.DataFrame({'ds': future_dates[-n_predict:]})
        
        forecast = self.model.predict(df_future)
        return forecast['yhat'].values

    def get_params(self, deep=True):
        return {
            "yearly_seasonality": self.yearly_seasonality,
            "weekly_seasonality": self.weekly_seasonality,
            "daily_seasonality": self.daily_seasonality,
        }

    def set_params(self, **params):
        for k, v in params.items():
            setattr(self, k, v)
        return self

# ==========================
# Enhanced LSTM Adapter with Auto Hyperparameters and Fixed Training Logic
# ==========================
if TORCH_AVAILABLE:
    class LSTMTSAdapter(BaseEstimator):
        class LSTMModel(nn.Module):
            def __init__(self, input_size=1, hidden_size=50, num_layers=1):
                super().__init__()
                self.lstm = nn.LSTM(input_size, hidden_size, num_layers, batch_first=True)
                self.fc = nn.Linear(hidden_size, 1)
            
            def forward(self, x):
                out, _ = self.lstm(x)
                out = self.fc(out[:, -1, :])
                return out

        def __init__(self, seq_length=None, hidden_size=50, num_layers=1, lr=0.001, epochs=50, batch_size=32, device=None):
            self.seq_length = seq_length
            self.hidden_size = hidden_size
            self.num_layers = num_layers
            self.lr = lr
            self.epochs = epochs
            self.batch_size = batch_size
            self.device = device if device else ('cuda' if torch.cuda.is_available() else 'cpu')
            self.model = None
            self.train_series = None

        def create_sequences(self, series):
            """Create sequences for proper next-step prediction"""
            X, y = [], []
            for i in range(len(series) - self.seq_length):
                X.append(series[i:i+self.seq_length])
                y.append(series[i+self.seq_length])
            return np.array(X), np.array(y)

        def fit(self, X, y):
            if not TORCH_AVAILABLE:
                raise ImportError("PyTorch is required for LSTMTSAdapter")
                
            from torch.utils.data import DataLoader, TensorDataset
            
            series = np.array(y).astype(float)
            self.train_series = series
            
            # 🧠 AUTO HYPERPARAMETER OPTIMIZATION
            if self.seq_length is None:
                self.seq_length = recommend_lstm_seq_length(series)
            
            # ✅ FIXED: Proper sequence creation for next-step prediction
            X_seq, y_seq = self.create_sequences(series)
            X_seq = torch.tensor(X_seq, dtype=torch.float32).unsqueeze(-1)
            y_seq = torch.tensor(y_seq, dtype=torch.float32).unsqueeze(-1)
            dataset = TensorDataset(X_seq, y_seq)
            loader = DataLoader(dataset, batch_size=self.batch_size, shuffle=True)

            self.model = self.LSTMModel(input_size=1, hidden_size=self.hidden_size, num_layers=self.num_layers).to(self.device)
            optimizer = torch.optim.Adam(self.model.parameters(), lr=self.lr)
            criterion = nn.MSELoss()

            self.model.train()
            for epoch in range(self.epochs):
                for batch_X, batch_y in loader:
                    batch_X, batch_y = batch_X.to(self.device), batch_y.to(self.device)
                    optimizer.zero_grad()
                    output = self.model(batch_X)
                    loss = criterion(output, batch_y)
                    loss.backward()
                    optimizer.step()
            return self

        def predict(self, X=None):
            if self.model is None or self.train_series is None:
                raise ValueError("Model not fitted yet.")
                
            # Use last seq_length values from training series as seed for prediction
            n_forecast = len(X) if X is not None else 10
            series = self.train_series[-self.seq_length:].tolist()
            self.model.eval()
            preds = []
            with torch.no_grad():
                for _ in range(n_forecast):
                    x_input = torch.tensor(series[-self.seq_length:], dtype=torch.float32).unsqueeze(0).unsqueeze(-1).to(self.device)
                    pred = self.model(x_input)
                    next_val = pred.item()
                    preds.append(next_val)
                    series.append(next_val)
            return np.array(preds)

        def get_params(self, deep=True):
            return {
                "seq_length": self.seq_length,
                "hidden_size": self.hidden_size,
                "num_layers": self.num_layers,
                "lr": self.lr,
                "epochs": self.epochs,
                "batch_size": self.batch_size,
            }

        def set_params(self, **params):
            for k, v in params.items():
                setattr(self, k, v)
            return self

else:
    # Create placeholder classes when PyTorch is not available
    class LSTMTSAdapter(BaseEstimator):
        def __init__(self, seq_length=10, hidden_size=50, num_layers=1, lr=0.001, epochs=50, batch_size=32, device=None):
            self.seq_length = seq_length
            self.hidden_size = hidden_size
            self.num_layers = num_layers
            self.lr = lr
            self.epochs = epochs
            self.batch_size = batch_size
            raise ImportError("PyTorch is required for LSTMTSAdapter")
        
        def fit(self, X, y=None):
            raise ImportError("PyTorch is required for LSTMTSAdapter")
        
        def predict(self, X):
            raise ImportError("PyTorch is required for LSTMTSAdapter")
        
        def get_params(self, deep=True):
            return {
                "seq_length": self.seq_length,
                "hidden_size": self.hidden_size,
                "num_layers": self.num_layers,
                "lr": self.lr,
                "epochs": self.epochs,
                "batch_size": self.batch_size,
            }
        
        def set_params(self, **params):
            for k, v in params.items():
                setattr(self, k, v)
            return self

# =======================================
# DYNAMIC DATASET TYPE DETECTION
# =======================================
def detect_dataset_type(df):
    """Detects the dataset type based on columns and content"""
    if df is None or df.empty:
        return "structured"  # default fallback
    
    # pandas already imported globally
    import numpy as np
    
    # Time series detection: check for datetime column and numeric target
    datetime_cols = df.select_dtypes(include=['datetime64[ns]', 'datetime']).columns.tolist()
    numeric_cols = df.select_dtypes(include=[np.number]).columns.tolist()
    if datetime_cols and len(numeric_cols) >= 1:
        return "time_series"
    
    # NLP detection: presence of object/string columns with high cardinality
    text_cols = df.select_dtypes(include=['object', 'string']).columns.tolist()
    try:
        if any(df[col].nunique() > 50 and df[col].dtype == 'object' for col in text_cols):
            return "nlp"
    except (TypeError, AttributeError):
        # Skip if columns contain unhashable types like lists
        pass
    
    # Image detection: columns ending with _img or array-like dtype
    for col in df.columns:
        if col.endswith("_img") or col.endswith("_image"):
            return "image"
        # Check for array-like data that could be flattened images
        if df[col].dtype == object and len(df) > 0:
            try:
                sample = df[col].iloc[0]
                if isinstance(sample, (list, np.ndarray)) and len(sample) > 100:
                    return "image"
            except:
                pass
    
    # Default fallback: structured/tabular
    return "structured"

def detect_dataset_size_category(df):
    """Categorizes dataset size as small, medium, or large"""
    if df is None:
        return "small"
    
    n_rows = df.shape[0]
    if n_rows < 5000:
        return "small"
    elif n_rows < 100000:
        return "medium"
    else:
        return "large"

