    def _get_neural_network_params(self, size, n_rows, n_features, problem_type):
        """Comprehensive Neural Network (MLP) hyperparameter recommendations with 20+ parameters."""
        
        # Dataset-aware architecture scaling
        if size == "small":
            hidden_layers_default = (64, 32)
            max_iter_default = 500
            batch_size_default = min(32, n_rows // 5)
            learning_rate_init_default = 0.001
            alpha_default = 0.01  # Higher regularization for small data
        elif size == "medium":
            hidden_layers_default = (128, 64, 32)
            max_iter_default = 1000
            batch_size_default = min(128, n_rows // 10)
            learning_rate_init_default = 0.001
            alpha_default = 0.001
        else:  # large
            hidden_layers_default = (256, 128, 64)
            max_iter_default = 2000
            batch_size_default = min(256, n_rows // 20)
            learning_rate_init_default = 0.0005
            alpha_default = 0.0001  # Lower regularization for large data
        
        # Feature-aware architecture adjustments
        if n_features < 10:
            # Small feature space - simpler architecture
            if size == "small":
                hidden_layers_default = (32,)
            elif size == "medium":
                hidden_layers_default = (64, 32)
            else:
                hidden_layers_default = (128, 64)
        elif n_features > 1000:
            # High-dimensional - deeper architecture with more regularization
            if size == "small":
                hidden_layers_default = (128, 64, 32)
                alpha_default = 0.1
            elif size == "medium":
                hidden_layers_default = (256, 128, 64, 32)
                alpha_default = 0.01
            else:
                hidden_layers_default = (512, 256, 128, 64)
