    def _get_prophet_params(self, size, n_rows, n_features):
        """Comprehensive Prophet hyperparameter recommendations with 15+ parameters."""
        
        # Changepoint prior scaling based on dataset size and your excellent guidance  
        if size == "small":
            changepoint_prior_default = 0.01  # Conservative for small data
            seasonality_prior_default = 10.0
            n_changepoints_default = 10
        elif size == "medium":
            changepoint_prior_default = 0.05  # Moderate flexibility
            seasonality_prior_default = 5.0
            n_changepoints_default = 25
        else:  # large
            changepoint_prior_default = 0.1   # More flexible for large data
            seasonality_prior_default = 1.0
            n_changepoints_default = 50
        
        # Intelligent seasonality detection based on data characteristics
        yearly_seasonality = n_rows > 365
        weekly_seasonality = n_rows > 30   # At least a month of data
        daily_seasonality = n_rows > 100   # At least 3+ months of hourly data
        
        # Seasonality mode selection (per your table guidance)
        if size == "small":
            seasonality_mode_default = "additive"  # Simpler for small data
        else:
            seasonality_mode_default = "additive"  # Start conservative
        
        # Growth model selection
        growth_default = "linear"  # Start with linear growth
        
        # Holiday effects scaling
        if n_rows > 365:
            holidays_prior_default = 10.0  # Standard for yearly+ data
        else:
            holidays_prior_default = 5.0   # Conservative for shorter series
        
        # Interval width for uncertainty
        interval_width_default = 0.80  # 80% confidence intervals
        
        # MCMC samples for uncertainty quantification
        mcmc_samples_default = 0  # Disabled by default (faster)
        
        # Comprehensive parameter set (15+ parameters)
        defaults = {
            # Core Prophet parameters
            "changepoint_prior_scale": changepoint_prior_default,  # Trend flexibility
            "seasonality_prior_scale": seasonality_prior_default,  # Seasonality strength
            "holidays_prior_scale": holidays_prior_default,        # Holiday effects
            "seasonality_mode": seasonality_mode_default,          # Additive vs multiplicative
            "growth": growth_default,                              # Linear vs logistic
            
            # Seasonality configuration
            "yearly_seasonality": yearly_seasonality,
            "weekly_seasonality": weekly_seasonality,
            "daily_seasonality": daily_seasonality,
            
            # Changepoint detection
            "n_changepoints": n_changepoints_default,              # Number of potential changepoints
            "changepoint_range": 0.8,                             # Proportion of history for changepoints
            "changepoints": None,                                  # Custom changepoint dates
            
            # Uncertainty quantification
            "interval_width": interval_width_default,              # Prediction interval width
            "uncertainty_samples": 1000,                          # Samples for uncertainty
            "mcmc_samples": mcmc_samples_default,                  # MCMC for full Bayesian inference
            
            # Advanced parameters
            "stan_backend": None,                                  # Stan backend (None = automatic)
            "scaling": "absmax",                                   # Feature scaling method
            "holidays": None,                                      # Custom holidays dataframe
            "seasonality_prior_scale": seasonality_prior_default, # Seasonality regularization
            "changepoint_prior_scale": changepoint_prior_default, # Trend change regularization
        }
        
        # Add logistic growth parameters if needed
        if growth_default == "logistic":
            defaults["cap"] = None          # Carrying capacity (required for logistic)
            defaults["floor"] = None        # Minimum value (optional)
        
        # Comprehensive search space (following your excellent ranges)
