def get_time_series_model(model_name: str, hyperparams: Optional[dict] = None):
    """
    Factory function to create time series models with hyperparameters.
    
    Args:
        model_name: Name of the time series model
        hyperparams: Dictionary of hyperparameters for the model
    
    Returns:
        Instantiated time series adapter
    """
    hyperparams = hyperparams or {}
    
    if model_name == "ARIMA":
        return ARIMAAdapter(**hyperparams)
    elif model_name == "Prophet":
        return ProphetAdapter(**hyperparams)
    elif model_name == "Holt-Winters":
        return HoltWintersAdapter(**hyperparams)
    elif model_name == "LSTM Time Series":
        return LSTMTSAdapter(**hyperparams)
    else:
        raise ValueError(f"Unknown time series model: {model_name}")

