# PIPELINE BUILDER FOR TIME SERIES ADAPTERS
# =======================================

def build_pipelines(algorithms: dict) -> dict:
    """
    Convert algorithms dictionary (from get_hybrid_algorithms) into pipelines.
    Works for both sklearn models and custom adapters (ARIMA, Prophet, etc.).
    """
    pipelines = {}

    for algo_name, model_instance in algorithms.items():
        try:
            # ✅ Accept anything that looks sklearn-like (fit/predict)
            if hasattr(model_instance, "fit") and hasattr(model_instance, "predict"):
                pipelines[algo_name] = model_instance
            else:
                print(f"⚠️ Skipping {algo_name} - not sklearn-compatible")
        except Exception as e:
            print(f"❌ Failed to register {algo_name}: {e}")

    return pipelines

