def sizeof_fmt(num: int) -> str:
    """Human readable file size"""
    for unit in ['B','KB','MB','GB','TB','PB']:
        if abs(num) < 1024.0:
            return f"{num:3.1f}{unit}"
        num /= 1024.0
    return f"{num:.1f}EB"

def human_size(nbytes: int) -> str:
    """Convert bytes to human-readable units."""
    suffixes = ['B', 'KB', 'MB', 'GB', 'TB']
    i = 0
    while nbytes >= 1024 and i < len(suffixes)-1:
        nbytes /= 1024.0
        i += 1
    return f"{nbytes:.2f} {suffixes[i]}"

def safe_name(name: str) -> str:
    """Flatten nested path to safe dataset key"""
    return name.replace('/', '_').replace('\\', '_')

def is_archive(name: str) -> bool:
    n = name.lower()
    return n.endswith('.zip') or n.endswith('.tar') or n.endswith('.tar.gz') or n.endswith('.tgz')

def load_table_from_fileobj(file_obj: io.BytesIO, filename: str, chunk_threshold_gb: float=DEFAULT_CHUNK_GB):
    """
    Load a supported file from a file-like object with progress tracking.
    Returns either a pandas DataFrame or a pandas TextFileReader (iterator) for chunked CSVs.
    """
    fn = filename.lower()
    ext = '.' + fn.split('.')[-1] if '.' in fn else ''
    try:
        if ext == '.csv':
            # detect size if possible (BytesIO length)
            try:
                file_obj.seek(0, os.SEEK_END)
                size = file_obj.tell()
                file_obj.seek(0)
            except Exception:
                size = None
            
            size_mb = (size or 0) / (1024**2)
            size_gb = (size or 0) / (1024**3)
            
            # PERFORMANCE FIX: Lower threshold to 50MB instead of 1GB to prevent WebSocket timeouts
            if size_mb > 50:
                # Chunked reading with progress bar
                with st.spinner(f"📖 Reading {filename} ({size_mb:.1f}MB)..."):
                    chunks = []
                    chunk_size = 50000  # rows per chunk
                    
                    progress_bar = st.progress(0)
                    status_text = st.empty()
                    
                    try:
                        reader = pd.read_csv(file_obj, chunksize=chunk_size)
                        chunk_count = 0
                        
                        for chunk in reader:
                            chunks.append(chunk)
                            chunk_count += 1
                            rows_loaded = chunk_count * chunk_size
                            
                            # Update progress every 5 chunks to avoid too many UI updates
                            if chunk_count % 5 == 0:
                                progress_bar.progress(min(0.95, chunk_count * chunk_size * 200 / (size or 1)))
                                status_text.text(f"📊 Loaded {rows_loaded:,} rows...")
                        
                        progress_bar.progress(1.0)
                        status_text.text(f"✅ Loaded {sum(len(c) for c in chunks):,} total rows")
                        
                        df = pd.concat(chunks, ignore_index=True)
                        
                        # Clear progress indicators
                        progress_bar.empty()
                        status_text.empty()
                        
                        return df
                    except Exception as e:
                        progress_bar.empty()
                        status_text.empty()
                        raise e
            else:
                # Standard read for smaller files (< 50MB)
                with st.spinner(f"📖 Reading {filename} ({size_mb:.1f}MB)..."):
                    return pd.read_csv(file_obj)
        elif ext in ('.xlsx', '.xls'):
            return pd.read_excel(file_obj)
        elif ext == '.json':
            # try JSON lines then fallback
            try:
                return pd.read_json(file_obj, lines=True)
            except ValueError:
                file_obj.seek(0)
                return pd.read_json(file_obj)
        elif ext == '.parquet':
            # pandas supports reading from a file-like with pyarrow engine
            return pd.read_parquet(file_obj)
        elif ext == '.tsv':
            return pd.read_csv(file_obj, sep='\t')
        elif ext == '.txt':
            # try csv then tsv
            try:
                return pd.read_csv(file_obj)
            except Exception:
                file_obj.seek(0)
                return pd.read_csv(file_obj, sep='\t')
        else:
            raise ValueError(f"Unsupported extension: {ext}")
    except Exception as e:
        raise

def load_file(path: Path, chunk_threshold_gb=1):
    """Load a single file with format detection and chunking."""
    ext = path.suffix.lower()
    size = path.stat().st_size
    readable_size = human_size(size)

    try:
        if ext in [".csv", ".txt", ".tsv"]:
            sep = "," if ext != ".tsv" else "\t"
            if size > chunk_threshold_gb * 1024**3:
                return pd.read_csv(path, sep=sep, chunksize=200_000), f"{readable_size} (chunked)"
            return pd.read_csv(path, sep=sep), readable_size

        elif ext in [".xlsx", ".xls"]:
            return pd.read_excel(path), readable_size
        elif ext == ".json":
            try:
                return pd.read_json(path, lines=True), readable_size
            except:
                return pd.read_json(path), readable_size
        elif ext == ".parquet":
            return pd.read_parquet(path), readable_size
        else:
            return None, f"Unsupported format: {ext}"

    except Exception as e:
        return None, f"Error: {str(e)}"

