def env_is_local() -> bool:
    """Detect if running locally vs cloud/Replit"""
    ov = st.session_state.get("env_mode_override")
    if ov:
        return ov == "Local"
    return not bool(os.environ.get("REPL_ID"))

def is_supported(name: str) -> bool:
    """Check if file extension is supported"""
    n = name.lower()
    return any(n.endswith(ext) for ext in SUPPORTED_EXTS)

def flatten_name(path: str) -> str:
    """Flatten path separators for consistent naming"""
    return path.replace("\\", "_").replace("/", "_")

def is_archive(name: str) -> bool:
    """Check if file is an archive"""
    n = name.lower()
    return n.endswith(".zip") or n.endswith(".tar") or n.endswith(".tar.gz") or n.endswith(".tgz")

def load_dataframe_from_bytes(b: bytes, filename: str, chunk_threshold_gb: float) -> Union[pd.DataFrame, Iterator[pd.DataFrame], None]:
    """Enhanced bytes to DataFrame loader with better error handling"""
    bio = io.BytesIO(b)
    fname = filename.lower()
    try:
        if fname.endswith(".csv") or fname.endswith(".txt"):
            size_gb = len(b) / (1024**3)
            if size_gb > chunk_threshold_gb:
                return pd.read_csv(bio, chunksize=READ_CHUNK_ROWS, low_memory=False)
            try:
                bio.seek(0)
                return pd.read_csv(bio, low_memory=False)
            except Exception:
                bio.seek(0)
                return pd.read_csv(bio, sep="\t", low_memory=False)

        if fname.endswith(".tsv"):
            return pd.read_csv(bio, sep="\t", low_memory=False)

        if fname.endswith(".xlsx") or fname.endswith(".xls"):
            return pd.read_excel(bio)

        if fname.endswith(".json"):
            try:
                bio.seek(0)
                return pd.read_json(bio, lines=True)
            except Exception:
                bio.seek(0)
                return pd.read_json(bio)

        if fname.endswith(".parquet"):
            bio.seek(0)
            return pd.read_parquet(bio)

    except Exception as e:
        st.warning(f"Failed to parse {filename}: {e}")
        return None
    return None

def ensure_kaggle_installed():
    """Ensure platform package is installed"""
    try:
        import kaggle  # noqa: F401
        return True
    except Exception:
        try:
            subprocess.run([sys.executable, "-m", "pip", "install", "kaggle"], check=True)
            import kaggle  # noqa: F401
            return True
        except Exception as e:
            st.error(f"Failed to install kaggle package: {e}")
            return False

def download_from_kaggle_ref(dataset_ref: str, output_dir: Path, unzip=True) -> Path:
    """Download dataset using platform CLI"""
    if not ensure_kaggle_installed():
        raise RuntimeError("kaggle CLI not available and installation failed.")
    output_dir.mkdir(parents=True, exist_ok=True)
    cmd = ["kaggle", "datasets", "download", "-d", dataset_ref, "-p", str(output_dir)]
    if unzip:
        cmd.append("--unzip")
    subprocess.run(cmd, check=True)
    return output_dir

def parse_kaggle_url_to_ref(url_or_ref: str) -> str:
    """Parse project URL to dataset reference with improved format support"""
    s = url_or_ref.strip()
    
    # If it looks like it's already in username/dataset format, return as-is
    if "/" in s and not s.startswith("http") and "kaggle.com" not in s:
        return s
    
    # Handle Project URLs
    if "kaggle.com" in s:
        parts = s.rstrip("/").split("/")
        try:
            # Standard dataset URL: https://www.kaggle.com/datasets/username/dataset-name
            if "datasets" in parts:
                idx = parts.index("datasets")
                user = parts[idx+1]
                ds = parts[idx+2]
                return f"{user}/{ds}"
            # Alternative formats - look for username/dataset pattern
            elif len(parts) >= 2:
                # Find potential username/dataset pairs
                for i in range(len(parts)-1):
                    if parts[i] and parts[i+1] and not parts[i] in ['www', 'kaggle', 'com', 'datasets']:
                        return f"{parts[i]}/{parts[i+1]}"
        except (IndexError, ValueError):
            pass
        
        # If parsing failed, give a helpful error
        raise ValueError(f"Couldn't parse project URL: '{s}'. Please use format 'username/dataset-name' or the full dataset URL from Platform.")
    
    # If it doesn't contain kaggle.com, assume it's already in the right format
    return s

def detect_target_candidates(df: pd.DataFrame) -> List[str]:
    """Enhanced target column detection"""
    if not isinstance(df, pd.DataFrame):
        return []
    cols = list(df.columns)
    candidates = []
    for c in cols:
        lc = c.lower()
        if any(h in lc for h in TARGET_NAME_HINTS) or lc in TARGET_NAME_HINTS:
            candidates.append(c)
    for hint in ("survived", "target", "label"):
        for c in cols:
            if c.lower() == hint:
                candidates.append(c)
    return sorted(list(dict.fromkeys(candidates)))

# -------------------------
# Project Loader Functions
# -------------------------
def kaggle_cli_loader(competition_name: str, dest_folder: str = None) -> Dict[str, Union[pd.DataFrame, Iterator[pd.DataFrame]]]:
    """Downloads datasets using Platform CLI for competitions and loads them with caching"""
    # Extract the competition slug from the name/URL
    competition_slug = extract_competition_slug(competition_name)
    
    # Create persistent competition directory in workspace  
    if dest_folder is None:
        competitions_dir = Path("/home/runner/workspace/competitions")
        competitions_dir.mkdir(exist_ok=True)
        dest_folder = competitions_dir / competition_slug
    else:
        dest_folder = Path(dest_folder)
    
    dest_folder.mkdir(parents=True, exist_ok=True)

    # Check if dataset already exists
    if dest_folder.exists() and any(dest_folder.iterdir()):
        st.info(f"✅ Project dataset '{competition_slug}' already exists - reusing cached data")
        st.success(f"📁 Using existing datasets from {dest_folder}")
        return load_local_folder_for_competition(str(dest_folder))

    st.info(f"📥 Downloading Project datasets for '{project_slug}' ...")

    # Ensure kaggle credentials are configured
    if not ensure_kaggle_credentials():
        raise RuntimeError("Platform credentials not configured. Please set up your API credentials first.")

    # Execute Platform CLI for competition using the slug - WEBSOCKET TIMEOUT FIX
    try:
        cmd = ["kaggle", "competitions", "download", "-c", competition_slug, "-p", str(dest_folder), "--force"]
        with st.spinner(f"⬇️ Downloading project data from Platform... This may take several minutes for large datasets."):
            result = subprocess.run(cmd, check=True, capture_output=True, text=True)
        st.success(f"✅ Project datasets downloaded to {dest_folder}")
    except subprocess.CalledProcessError as e:
        # Provide more detailed error information
        error_msg = f"Platform CLI download failed for competition '{competition_slug}'"
        if e.stderr:
            error_msg += f"\nError details: {e.stderr}"
        if "403" in str(e.stderr):
            error_msg += "\nHint: Make sure you have accepted the competition rules on the platform"
        elif "404" in str(e.stderr):
            error_msg += f"\nHint: Competition '{competition_slug}' not found. Check the project name/URL."
        raise RuntimeError(error_msg)

    # Process downloaded files using existing loader logic
    return load_local_folder_for_competition(str(dest_folder))

def load_local_folder_for_competition(folder_path: str) -> Dict[str, Union[pd.DataFrame, Iterator[pd.DataFrame]]]:
    """Recursively loads all datasets in a project folder, including archives - WEBSOCKET TIMEOUT FIX"""
    datasets = {}
    folder = Path(folder_path)
    
    # Collect all files first
    all_files = [p for p in folder.rglob("*") if p.is_file()]
    
    if not all_files:
        return datasets
    
    # Add progress tracking to prevent WebSocket timeout
    load_progress = st.progress(0)
    load_status = st.empty()
    
    try:
        for idx, path in enumerate(all_files):
            try:
                # Update progress
                load_status.text(f"📂 Loading {path.name}... ({idx+1}/{len(all_files)})")
                
                if is_competition_archive(path.name):
                    nested = extract_and_load_competition_archive(path)
                    datasets.update(nested)
                else:
                    df = load_competition_data_file(path, path.name)
                    if df is not None:
                        datasets[path.name] = df
                
                # Update progress bar
                load_progress.progress((idx + 1) / len(all_files))
                
            except Exception as e:
                st.warning(f"Failed to load {path.name}: {e}")
    finally:
        # Always clear progress indicators
        load_progress.empty()
        load_status.empty()
    
    st.success(f"✅ Loaded {len(datasets)} datasets from project folder")
    return datasets

def is_competition_archive(filename: str) -> bool:
    """Check if file is an archive"""
    return filename.lower().endswith((".zip", ".tar", ".tar.gz", ".tgz"))

def extract_and_load_competition_archive(file_path: Path) -> Dict[str, Union[pd.DataFrame, Iterator[pd.DataFrame]]]:
    """Extracts ZIP/TAR archives and loads contained datasets - WEBSOCKET TIMEOUT FIX"""
    datasets = {}
    
    if file_path.suffix.lower() == ".zip":
        with zipfile.ZipFile(file_path, "r") as zip_ref:
            file_list = [f for f in zip_ref.namelist() if not f.startswith("__MACOSX/") and not f.endswith('/')]
            
            # Add progress tracking if multiple files
            if len(file_list) > 1:
                archive_progress = st.progress(0)
                archive_status = st.empty()
                
                try:
                    for idx, f in enumerate(file_list):
                        try:
                            archive_status.text(f"📦 Extracting {f} from ZIP... ({idx+1}/{len(file_list)})")
                            content = zip_ref.read(f)
                            df = load_dataframe_from_bytes(content, f, CHUNK_THRESHOLD_GB_DEFAULT)
                            if df is not None:
                                datasets[f.replace("/", "_")] = df
                            archive_progress.progress((idx + 1) / len(file_list))
                        except Exception as e:
                            st.warning(f"Failed to load {f} from ZIP: {e}")
                finally:
                    archive_progress.empty()
                    archive_status.empty()
            else:
                # Single file - no progress needed
                for f in file_list:
                    try:
                        content = zip_ref.read(f)
                        df = load_dataframe_from_bytes(content, f, CHUNK_THRESHOLD_GB_DEFAULT)
                        if df is not None:
                            datasets[f.replace("/", "_")] = df
                    except Exception as e:
                        st.warning(f"Failed to load {f} from ZIP: {e}")
                        
    elif file_path.suffix.lower() in [".tar", ".tgz", ".tar.gz"]:
        with tarfile.open(file_path, "r:*") as tar_ref:
            members = [m for m in tar_ref.getmembers() if m.isfile()]
            
            # Add progress tracking if multiple files
            if len(members) > 1:
                archive_progress = st.progress(0)
                archive_status = st.empty()
                
                try:
                    for idx, member in enumerate(members):
                        try:
                            archive_status.text(f"📦 Extracting {member.name} from TAR... ({idx+1}/{len(members)})")
                            extracted = tar_ref.extractfile(member)
                            if extracted:
                                content = extracted.read()
                                df = load_dataframe_from_bytes(content, member.name, CHUNK_THRESHOLD_GB_DEFAULT)
                                if df is not None:
                                    datasets[member.name.replace("/", "_")] = df
                            archive_progress.progress((idx + 1) / len(members))
                        except Exception as e:
                            st.warning(f"Failed to load {member.name} from TAR: {e}")
                finally:
                    archive_progress.empty()
                    archive_status.empty()
            else:
                # Single file - no progress needed
                for member in members:
                    try:
                        extracted = tar_ref.extractfile(member)
                        if extracted:
                            content = extracted.read()
                            df = load_dataframe_from_bytes(content, member.name, CHUNK_THRESHOLD_GB_DEFAULT)
                            if df is not None:
                                datasets[member.name.replace("/", "_")] = df
                    except Exception as e:
                        st.warning(f"Failed to load {member.name} from TAR: {e}")
    return datasets

def load_competition_data_file(file_path: Path, filename: str) -> Union[pd.DataFrame, Iterator[pd.DataFrame], None]:
    """Loads a project data file based on its extension"""
    try:
        with open(file_path, 'rb') as f:
            content = f.read()
        return load_dataframe_from_bytes(content, filename, CHUNK_THRESHOLD_GB_DEFAULT)
    except Exception as e:
        st.warning(f"Failed to load {filename}: {e}")
        return None

def extract_and_load_zip(b: bytes, chunk_threshold_gb: float) -> Dict[str, Union[pd.DataFrame, Iterator[pd.DataFrame]]]:
    """Enhanced ZIP extraction with nested archive support"""
    out = {}
    try:
        with zipfile.ZipFile(io.BytesIO(b)) as zf:
            for name in zf.namelist():
                if name.endswith("/") or "__MACOSX" in name:
                    continue
                if not is_supported(name) and not is_archive(name):
                    continue
                # nested archive support
                raw = zf.read(name)
                if is_archive(name):
                    if name.lower().endswith(".zip"):
                        out.update(extract_and_load_zip(raw, chunk_threshold_gb))
                    else:
                        out.update(extract_and_load_tar(raw, chunk_threshold_gb))
                    continue
                df = load_dataframe_from_bytes(raw, name, chunk_threshold_gb)
                if df is not None:
                    out[flatten_name(name)] = df
    except Exception as e:
        st.warning(f"Failed to extract ZIP: {e}")
    return out

def extract_and_load_tar(b: bytes, chunk_threshold_gb: float) -> Dict[str, Union[pd.DataFrame, Iterator[pd.DataFrame]]]:
    """Enhanced TAR extraction with nested archive support"""
    out = {}
    try:
        with tarfile.open(fileobj=io.BytesIO(b), mode="r:*") as tf:
            for member in tf.getmembers():
                if member.isdir() or "__MACOSX" in member.name:
                    continue
                if not is_supported(member.name) and not is_archive(member.name):
                    continue
                f = tf.extractfile(member)
                if not f:
                    continue
                raw = f.read()
                if is_archive(member.name):
                    if member.name.lower().endswith(".zip"):
                        out.update(extract_and_load_zip(raw, chunk_threshold_gb))
                    else:
                        out.update(extract_and_load_tar(raw, chunk_threshold_gb))
                    continue
                df = load_dataframe_from_bytes(raw, member.name, chunk_threshold_gb)
                if df is not None:
                    out[flatten_name(member.name)] = df
    except Exception as e:
        st.warning(f"Failed to extract TAR: {e}")
    return out

