def image_zip_to_arrays(zip_bytes: bytes, target_image_size: Tuple[int,int]=(128,128)) -> Tuple[List[np.ndarray], List[str]]:
    """
    Load images and labels from a ZIP archive bytes.
    - Supports folder-per-class structure (folder names are labels).
    - Supports an optional labels.csv in the root with columns: filename,label
    Returns (images_as_numpy_arrays, labels_as_strings)
    """
    if not PIL_AVAILABLE:
        raise RuntimeError("Pillow is required for image processing. Install pillow and retry.")
    images = []
    labels = []
    with zipfile.ZipFile(io.BytesIO(zip_bytes)) as zf:
        file_list = [f for f in zf.namelist() if not f.endswith('/') and not f.startswith('__MACOSX/')]
        # detect labels.csv or mapping file
        mapping = {}
        if any(Path(f).name.lower() == 'labels.csv' for f in file_list):
            # read labels.csv
            label_files = [f for f in file_list if Path(f).name.lower() == 'labels.csv']
            # take the first occurrence
            lf = label_files[0]
            with zf.open(lf) as fh:
                try:
                    df = pd.read_csv(fh)
                except Exception:
                    fh.seek(0)
                    df = pd.read_csv(io.TextIOWrapper(fh, encoding='utf-8'))
                # expects columns filename,label
                if 'filename' in df.columns and 'label' in df.columns:
                    for _, row in df.iterrows():
                        mapping[str(row['filename']).strip()] = str(row['label']).strip()

        # process files
        for f in file_list:
            ext = Path(f).suffix.lower()
            if ext not in ['.jpg', '.jpeg', '.png', '.bmp', '.gif', '.tif', '.tiff']:
                continue
            with zf.open(f) as fh:
                try:
                    img = Image.open(fh).convert('RGB')
                except Exception:
                    continue
                # Resize to target_image_size
                img = img.resize(target_image_size, Image.BILINEAR)
                arr = np.array(img)  # H x W x C
                # Determine label: mapping > folder name > unknown
                filename = Path(f).name
                label = None
                if filename in mapping:
                    label = mapping[filename]
                else:
                    parts = Path(f).parts
                    # if inside a folder structure, take parent folder as label
                    if len(parts) >= 2:
                        label = parts[-2]
                    else:
                        label = 'unknown'
                images.append(arr)
                labels.append(label)
    return images, labels

def human_size(num_bytes: int) -> str:
    """Convert bytes to human-readable format"""
    for unit in ['B','KB','MB','GB','TB']:
        if num_bytes < 1024.0:
            return f"{num_bytes:3.1f}{unit}"
        num_bytes /= 1024.0
    return f"{num_bytes:.1f}PB"

