if TORCH_AVAILABLE:
    class ImageFolderDataset(Dataset):
        def __init__(self, images: List[np.ndarray], labels: List[int], transform=None):
            self.images = images
            self.labels = labels
            self.transform = transform

        def __len__(self):
            return len(self.images)

        def __getitem__(self, idx):
            arr = self.images[idx]
            # arr: H x W x C
            img = Image.fromarray(arr)
            if self.transform:
                img = self.transform(img)
            else:
                # default: convert to tensor and normalize to [0,1]
                img = transforms.ToTensor()(img)
            label = int(self.labels[idx])
            return img, label

    class DynamicSimpleCNN(nn.Module):
        """A simple CNN that can dynamically compute flattened size given a sample input."""
        def __init__(self, in_channels=3, conv_channels=(16,32), num_classes=2, image_size=(128,128), dropout=0.2):
            super().__init__()
            layers = []
            last_ch = in_channels
            for ch in conv_channels:
                layers.append(nn.Conv2d(last_ch, ch, kernel_size=3, padding=1))
                layers.append(nn.BatchNorm2d(ch))
                layers.append(nn.ReLU(inplace=True))
                layers.append(nn.MaxPool2d(2))
                last_ch = ch
            self.features = nn.Sequential(*layers)
            # compute flattened dim dynamically
            with torch.no_grad():
                dummy = torch.zeros(1, in_channels, image_size[0], image_size[1])
                feat = self.features(dummy)
                self.flattened_dim = int(np.prod(feat.shape[1:]))
            self.classifier = nn.Sequential(
                nn.Flatten(),
                nn.Dropout(dropout),
                nn.Linear(self.flattened_dim, max(64, num_classes*4)),
                nn.ReLU(inplace=True),
                nn.Linear(max(64, num_classes*4), num_classes)
            )

        def forward(self, x):
            x = self.features(x)
            x = self.classifier(x)
            return x

    def get_resnet_model(num_classes=2, pretrained=False):
        """Get ResNet18 model"""
        if not TORCHVISION_AVAILABLE:
            raise RuntimeError("torchvision is required for ResNet models.")
        model = models.resnet18(pretrained=pretrained)
        model.fc = nn.Linear(model.fc.in_features, num_classes)
        return model

    def get_efficientnet_model(num_classes=2, version='b0', pretrained=False):
        """Get EfficientNet model"""
        if not EFFICIENTNET_AVAILABLE:
            raise RuntimeError("efficientnet_pytorch not available.")
        model = EfficientNet.from_pretrained(f"efficientnet-{version}") if pretrained else EfficientNet.from_name(f"efficientnet-{version}")
        model._fc = nn.Linear(model._fc.in_features, num_classes)
        return model

    def train_pytorch_model(
        model: nn.Module,
        device,
        dataloader: DataLoader,
        val_loader: Optional[DataLoader],
        epochs: int = 5,
        lr: float = 1e-3,
        checkpoint_path: Optional[str] = None,
    ):
        """Enhanced PyTorch model training with better progress tracking"""
        optimizer = optim.Adam(model.parameters(), lr=lr)
        criterion = nn.CrossEntropyLoss()
        model.to(device)
        history = {'train_loss': [], 'train_acc': [], 'val_loss': [], 'val_acc': []}

        progress = st.progress(0)
        status_text = st.empty()
        for epoch in range(epochs):
            model.train()
            running_loss = 0.0
            correct = 0
            total = 0
            for i, (inputs, labels) in enumerate(dataloader):
                inputs = inputs.to(device)
                labels = labels.to(device)
                optimizer.zero_grad()
                outputs = model(inputs)
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()
                running_loss += loss.item() * inputs.size(0)
                _, preds = torch.max(outputs, 1)
                correct += torch.sum(preds == labels).item()
                total += labels.size(0)
            epoch_loss = running_loss / total if total>0 else 0.0
            epoch_acc = correct / total if total>0 else 0.0
            history['train_loss'].append(epoch_loss)
            history['train_acc'].append(epoch_acc)

            # validation
            if val_loader is not None:
                model.eval()
                v_loss = 0.0
                v_correct = 0
                v_total = 0
                with torch.no_grad():
                    for inputs, labels in val_loader:
                        inputs = inputs.to(device)
                        labels = labels.to(device)
                        outputs = model(inputs)
                        loss = criterion(outputs, labels)
                        v_loss += loss.item() * inputs.size(0)
                        _, preds = torch.max(outputs, 1)
                        v_correct += torch.sum(preds == labels).item()
                        v_total += labels.size(0)
                v_loss_epoch = v_loss / v_total if v_total>0 else 0.0
                v_acc = v_correct / v_total if v_total>0 else 0.0
                history['val_loss'].append(v_loss_epoch)
                history['val_acc'].append(v_acc)
                status_text.text(f"Epoch {epoch+1}/{epochs} — train_loss: {epoch_loss:.4f}, train_acc: {epoch_acc:.3f} — val_loss: {v_loss_epoch:.4f}, val_acc: {v_acc:.3f}")
            else:
                status_text.text(f"Epoch {epoch+1}/{epochs} — train_loss: {epoch_loss:.4f}, train_acc: {epoch_acc:.3f}")

            progress.progress((epoch+1)/epochs)

            # optional checkpoint
            if checkpoint_path:
                try:
                    torch.save(model.state_dict(), checkpoint_path)
                except Exception:
                    pass

        return model, history

    def get_resnet(num_classes=2, pretrained=False, device='cpu'):
        """Get ResNet18 model for image classification"""
        if not TORCHVISION_AVAILABLE:
            raise RuntimeError("torchvision is required for ResNet models.")
        model = models.resnet18(pretrained=pretrained)
        model.fc = nn.Linear(model.fc.in_features, num_classes)
        return model

    def get_efficientnet(num_classes=2, version='b0', pretrained=False):
        """Get EfficientNet model for image classification"""
        if not EFFICIENTNET_AVAILABLE:
            raise RuntimeError("efficientnet_pytorch not available.")
        model = EfficientNet.from_pretrained(f"efficientnet-{version}") if pretrained else EfficientNet.from_name(f"efficientnet-{version}")
        model._fc = nn.Linear(model._fc.in_features, num_classes)
        return model

def verify_local_path(path_str: str):
    """Utility to verify if a local path exists and preview its contents."""
    p = Path(path_str)

    if not p.exists():
        st.error(f"❌ Path not found: {path_str}")
        return None

    if p.is_file():
        st.success(f"✅ Found file: {p}")
        return [p]

    if p.is_dir():
        st.success(f"✅ Found directory: {p}")
        files = list(p.rglob("*"))
        if not files:
            st.warning("⚠️ Directory exists but is empty!")
            return []
        st.info(f"📂 Directory contains {len(files)} files/subfolders. Showing first 10:")
        for f in files[:10]:
            st.write("   -", f)
        return files

def scan_local_directory(dir_path: str, chunk_threshold_gb: float) -> Dict[str, Union[pd.DataFrame, Iterator[pd.DataFrame]]]:
    """Enhanced local directory scanning with better performance - WEBSOCKET TIMEOUT FIX"""
    out = {}
    base = Path(dir_path)
    if not base.exists():
        raise FileNotFoundError(f"Path not found: {dir_path}")
    
    # Collect all files first
    all_files = [p for p in base.rglob("*") if p.is_file()]
    
    if not all_files:
        return out
    
    # Add progress tracking to prevent WebSocket timeout
    scan_progress = st.progress(0)
    scan_status = st.empty()
    
    try:
        for idx, p in enumerate(all_files):
            try:
                name = p.name
                file_size_mb = p.stat().st_size / (1024**2)
                
                # Update progress
                scan_status.text(f"📂 Scanning {name} ({file_size_mb:.1f}MB)... ({idx+1}/{len(all_files)})")
                
                if is_archive(name):
                    raw = p.read_bytes()
                    if name.lower().endswith(".zip"):
                        out.update(extract_and_load_zip(raw, chunk_threshold_gb))
                    else:
                        out.update(extract_and_load_tar(raw, chunk_threshold_gb))
                    continue
                if is_supported(name):
                    raw = p.read_bytes()
                    df = load_dataframe_from_bytes(raw, name, chunk_threshold_gb)
                    if df is not None:
                        rel = p.relative_to(base).as_posix()
                        out[flatten_name(rel)] = df
                
                # Update progress bar
                scan_progress.progress((idx + 1) / len(all_files))
                
            except Exception as e:
                st.warning(f"Skipped {p}: {e}")
    finally:
        # Always clear progress indicators
        scan_progress.empty()
        scan_status.empty()
    
    return out

def detect_role_from_name(name: str) -> str:
    lname = name.lower()
    if any(k in lname for k in ['train', 'training', 'train_set', 'train-']):
        return 'train'
    if any(k in lname for k in ['test', 'testing', 'validation', 'val', 'holdout']):
        return 'test'
    if any(k in lname for k in ['predict', 'inference', 'unseen', 'scoring']):
        return 'predict'
    return 'unspecified'

def detect_target_column_from_df(df: pd.DataFrame, competition_text: str = "") -> Tuple[str, float, dict]:
    """
    Heuristic detection:
    - pattern matches on column names
    - checks numeric vs categorical heuristics
    - returns (best_column, confidence(0-1), reasoning)
    """
    if df is None or not hasattr(df, 'columns'):
        return 'unknown', 0.0, {'reason': 'no dataframe supplied'}

    cols = list(df.columns)
    text = competition_text.lower() if competition_text else ''
    patterns_high = ['target','label','survived','outcome','y','is_','has_','class','category','rating']
    patterns_medium = ['score','amount','price','cost','value','qty','count','quantity','rating','prob']
    scores = {}
    for c in cols:
        cl = c.lower()
        score = 0
        reasons = []
        for p in patterns_high:
            if re.search(r'\b' + re.escape(p) + r'\b', cl):
                score += 5
                reasons.append(f'pattern_high:{p}')
        for p in patterns_medium:
            if p in cl:
                score += 2
                reasons.append(f'pattern_med:{p}')
        # mention in competition text
        if cl in text:
            score += 4
            reasons.append('mentioned_in_description')
        # cardinality heuristic
        try:
            nunique = df[c].nunique(dropna=True)
            if nunique == 2:
                score += 3
                reasons.append('binary_candidate')
            elif nunique <= 20 and nunique > 2:
                score += 2
                reasons.append('low_cardinality_multi')
            # numeric heuristic -> regression candidate
            if pd.api.types.is_numeric_dtype(df[c]) and nunique > 20:
                score += 1
                reasons.append('numeric_high_cardinality')
        except Exception:
            pass
        if score > 0:
            scores[c] = {'score': score, 'reasons': reasons}

    if not scores:
        return 'unknown', 0.0, {'reason': 'no matching columns'}

    # pick best
    best = max(scores.items(), key=lambda kv: kv[1]['score'])
    best_col, best_info = best[0], best[1]
    total = sum(v['score'] for v in scores.values())
    confidence = best_info['score'] / total if total > 0 else 0.0
    confidence = min(confidence, 1.0)
    return best_col, confidence, {'all_candidates': scores, 'best_reasons': best_info['reasons']}

def auto_feature_engineering_suggestions(df: pd.DataFrame, sample_rows: int = 500) -> Dict[str, Any]:
    """
    Returns a structured set of suggestions:
    - numeric columns, categorical columns
    - missing value handling suggestions
    - datetime detection -> suggest extracting features
    - categorical encoding suggestions
    - scaling suggestion
    """
    out = {'numeric': [], 'categorical': [], 'datetime': [], 'missing_values': {}, 'suggestions': []}
    if df is None or not hasattr(df, 'columns'):
        return out
    # sample to speed up dtype inference
    try:
        sample = df.head(sample_rows).copy()
    except Exception:
        sample = df.copy()

    for c in sample.columns:
        ser = sample[c]
        dtype = ser.dtype
        if pd.api.types.is_numeric_dtype(dtype):
            out['numeric'].append(c)
        elif pd.api.types.is_datetime64_any_dtype(dtype):
            out['datetime'].append(c)
        else:
            # try parse datetime candidates
            try:
                if ser.dropna().astype(str).str.match(r'^\d{4}-\d{2}-\d{2}').any():
                    out['datetime'].append(c)
                else:
                    out['categorical'].append(c)
            except Exception:
                out['categorical'].append(c)

        # missing values
        null_pct = float(ser.isna().mean())
        if null_pct > 0:
            out['missing_values'][c] = f"{null_pct:.2%} missing"
            if pd.api.types.is_numeric_dtype(dtype):
                out['suggestions'].append(f"Impute numeric column '{c}' with median or mean (median preferred for skew).")
            else:
                out['suggestions'].append(f"Impute categorical/text column '{c}' with mode or 'missing' token.")

    # general suggestions
    if out['datetime']:
        out['suggestions'].append("Extract datetime features (year, month, day, dayofweek, hour) from datetime columns.")
    if out['categorical']:
        out['suggestions'].append("Consider target/mean encoding or one-hot encoding for categorical features (watch cardinality).")
    if out['numeric']:
        out['suggestions'].append("Consider scaling numeric features (StandardScaler/MinMax) for distance-based models.")
    out['summary'] = {
        'n_columns': len(sample.columns),
        'n_numeric': len(out['numeric']),
        'n_categorical': len(out['categorical']),
        'n_datetime': len(out['datetime']),
        'missing_value_columns': len(out['missing_values'])
    }
    return out

