    def process_text(self, text: str) -> Dict[str, Any]:
        """
        Main entry: returns structured analysis of the pasted text.
        """
        if not text or not text.strip():
            return {
                'insights_text': '',
                'signals': {},
                'keywords': [],
                'raw': text
            }

        text_clean = re.sub(r'\s+', ' ', text).strip()
        keywords = self._extract_keywords(text_clean)
        signals = self._detect_signals(text_clean, keywords)
        insights_text = self._compose_insights(signals, keywords, text_clean)

        return {
            'insights_text': insights_text,
            'signals': signals,
            'keywords': keywords,
            'raw': text_clean
        }

    def _extract_keywords(self, text: str) -> List[str]:
        """
        Extract candidate keywords:
        - Prefer spaCy noun_chunks / entities when available
        - Fallback: top frequent words minus stopwords (simple heuristic)
        """
        text_l = text.lower()
        keywords = []

        if ADVANCED_NLP_AVAILABLE and NLP_MODEL:
            try:
                doc = NLP_MODEL(text)
                # Named entities and noun chunks
                ents = [ent.text.lower() for ent in doc.ents if len(ent.text) > 1]
                noun_chunks = [nc.text.lower() for nc in doc.noun_chunks if len(nc.text) > 1]
                keywords = list(dict.fromkeys(ents + noun_chunks))  # preserve order, unique
            except Exception:
                keywords = []
        if not keywords:
            # Simple fallback: take frequent 1-2 word tokens excluding stopwords & short tokens
            tokens = re.findall(r"[a-zA-Z0-9\-]{3,}", text_l)
            freq = {}
            for t in tokens:
                freq[t] = freq.get(t, 0) + 1
            # top 25 tokens
            keywords = [k for k, _ in sorted(freq.items(), key=lambda i: i[1], reverse=True)][:25]

        return keywords

    def _detect_signals(self, text: str, keywords: List[str]) -> Dict[str, Dict[str, Any]]:
        """
        For each domain in DOMAIN_KEYWORDS, compute a confidence [0..1] based on occurrences
        and presence in keywords. Return signals dict with confidence and matched terms.
        """
        text_l = text.lower()
        signals = {}
        for domain, patterns in self.DOMAIN_KEYWORDS.items():
            matches = []
            score = 0
            for p in patterns:
                if p in text_l:
                    matches.append(p)
                    score += 2  # direct substring strong signal
            # check keywords presence (weigh less)
            for kw in keywords:
                for p in patterns:
                    if p in kw and kw not in matches:
                        matches.append(kw)
                        score += 1
            # normalize roughly to [0,1] by dividing by a heuristic max (len(patterns)*2)
            max_possible = max(1, len(patterns) * 2)
            confidence = min(1.0, score / max_possible)
            if confidence > 0:
                signals[domain] = {
                    'confidence': round(confidence, 3),
                    'matches': matches
                }
        return signals

    def _compose_insights(self, signals: Dict[str, Any], keywords: List[str], text: str) -> str:
        """
        Build a human-friendly multi-line summary from signals and keywords.
        """
        lines = []
        if not signals:
            lines.append("No strong domain-specific signals detected in the pasted content.")
            # add short generic hints
            if len(keywords) > 0:
                lines.append(f"Top keywords detected: {', '.join(keywords[:10])}")
            return "\n".join(lines)

        # ordered by confidence desc
        ordered = sorted(signals.items(), key=lambda kv: kv[1]['confidence'], reverse=True)
        for domain, info in ordered:
            conf = info['confidence']
            matches = ", ".join(info['matches'][:6]) if info['matches'] else "—"
            friendly = self._domain_label(domain)
            lines.append(f"{friendly}: confidence {conf:.0%}; matched terms: {matches}.")
        # add short keywords line
        if keywords:
            lines.append("Top keywords: " + ", ".join(keywords[:12]))
        # add a recommendation sentence
        lines.append("Recommendation: use these signals to prioritize architectures, validation, and feature engineering.")
        return "\n".join(lines)

    def _domain_label(self, domain_key: str) -> str:
        mapping = {
            'biology_sequence': 'Biology / Sequence data',
            'image_cv': 'Computer Vision / Image data',
            'time_series': 'Time-series / Sequential data',
            'nlp_text': 'NLP / Text data',
            'graph_spatial': 'Graph / Spatial / 3D data',
            'tabular_structured': 'Tabular / Structured data',
            'imbalance': 'Imbalanced class signals',
            'custom_metric': 'Custom evaluation metric mentioned',
            'multimodal': 'Multimodal signals'
        }
        return mapping.get(domain_key, domain_key)
    
