    def detect_evaluation_metric(self, competition_data: Dict[str, Any]) -> Dict[str, Any]:
        """Detect the evaluation metric used in the competition"""
        text_to_analyze = " ".join([
            competition_data.get('evaluation', ''),
            competition_data.get('description', ''),
            competition_data.get('overview', '')
        ]).lower()
        
        metric_scores = {}
        matched_details = {}
        
        for metric, keywords in self.metric_keywords.items():
            score = 0
            matched_keywords = []
            
            for keyword in keywords:
                # Exact word boundary match
                exact_count = len(re.findall(r'\b' + re.escape(keyword.lower()) + r'\b', text_to_analyze))
                if exact_count > 0:
                    score += exact_count * 2
                    matched_keywords.append(f"exact:{keyword}")
                
                # Fuzzy fallback for variations
                fuzzy_matches = len(re.findall(rf'{re.escape(keyword.lower())}\w*', text_to_analyze))
                fuzzy_bonus = max(0, fuzzy_matches - exact_count)
                if fuzzy_bonus > 0:
                    score += fuzzy_bonus
                    matched_keywords.append(f"fuzzy:{keyword}")
            
            metric_scores[metric] = score
            matched_details[metric] = matched_keywords
        
        if not metric_scores or all(score == 0 for score in metric_scores.values()):
            return {
                "best_guess": 'unknown',
                "confidence": 0.0,
                "candidates": {},
                "detected_metrics": []
            }
        
        # Sort by score
        sorted_metrics = sorted(metric_scores.items(), key=lambda x: x[1], reverse=True)
        best_metric = sorted_metrics[0][0]
        total_score = sum(metric_scores.values())
        confidence = metric_scores[best_metric] / total_score if total_score > 0 else 0
        
        # Get all metrics with non-zero scores
        detected_metrics = [metric for metric, score in metric_scores.items() if score > 0]
        
        return {
            "best_guess": best_metric,
            "confidence": round(confidence, 3),
            "candidates": {
                metric: {
                    "score": score,
                    "confidence": round(score / total_score, 3) if total_score > 0 else 0,
                    "matched_keywords": matched_details[metric]
                }
                for metric, score in sorted_metrics if score > 0
            },
            "detected_metrics": detected_metrics,
            "all_scores": metric_scores
        }

