class CompetitionAnalyzer:
    """Comprehensive competition analysis with Platform API integration"""
    
    def __init__(self):
        # Use persistent NLP processor from session state if available
        if 'nlp_processor' in st.session_state:
            self.nlp_processor = st.session_state.nlp_processor
        else:
            self.nlp_processor = AdvancedNLPProcessor()
            st.session_state.nlp_processor = self.nlp_processor
        self.problem_detector = ProblemDetector()
    
    def analyze_competition_comprehensive(self, competition_input: str, dataset_columns: List[str] = None) -> Dict[str, Any]:
        """
        Complete competition analysis from name/URL to structured recommendations
        
        Args:
            competition_input: Competition name or URL
            dataset_columns: List of dataset column names (if available)
        
        Returns:
            Structured JSON with comprehensive analysis
        """
        
        try:
            # Extract competition name from URL if needed
            competition_name = self._extract_competition_name(competition_input)
            
            # Fetch project data via Platform API
            competition_data = self._fetch_competition_metadata(competition_name)
            
            # Core analysis
            analysis_results = self._perform_comprehensive_analysis(competition_data, dataset_columns)
            
            # Format as structured JSON
            return self._format_json_response(analysis_results)
            
        except Exception as e:
            return self._error_response(str(e))
    
    def _extract_competition_name(self, competition_input: str) -> str:
        """Extract competition name from URL or return as-is"""
        if 'kaggle.com/competitions/' in competition_input:
            # Extract from URL: https://www.kaggle.com/competitions/titanic -> titanic
            return competition_input.split('/')[-1]
        elif 'kaggle.com/c/' in competition_input:
            # Extract from legacy URL: https://www.kaggle.com/c/titanic -> titanic  
            return competition_input.split('/')[-1]
        else:
            # Assume it's already a competition name
            return competition_input.strip()
    
    def _fetch_competition_metadata(self, competition_name: str) -> Dict[str, Any]:
        """Fetch competition metadata using Platform API"""
        try:
            import kaggle
            
            # Fetch competition details using correct API method
            competitions = kaggle.api.competitions_list(search=competition_name)
            competition = None
            
            # Find exact match
            for comp in competitions:
                if (hasattr(comp, 'ref') and comp.ref == competition_name) or \
                   (hasattr(comp, 'slug') and comp.slug == competition_name):
                    competition = comp
                    break
            
            if not competition and competitions:
                # If no exact match, take the first result
                competition = competitions[0]
            
            if not competition:
                raise Exception(f"Competition '{competition_name}' not found")
            
            # Fetch dataset information
            try:
                dataset_files = kaggle.api.competition_list_files(competition_name)
                dataset_info = [f.name for f in dataset_files]
            except:
                dataset_info = []
            
            # Handle tags properly - convert ApiCategory objects to strings
            raw_tags = getattr(competition, 'tags', []) or []
            tags_list = []
            if raw_tags:
                for tag in raw_tags:
                    if hasattr(tag, 'name'):
                        tags_list.append(str(tag.name))
                    elif hasattr(tag, 'displayName'):
                        tags_list.append(str(tag.displayName))
                    else:
                        tags_list.append(str(tag))
            
            return {
                'name': competition_name,
                'title': getattr(competition, 'title', '') or competition_name,
                'description': getattr(competition, 'description', '') or '',
                'overview': getattr(competition, 'description', '') or '',  # Use description as overview
                'evaluation': getattr(competition, 'evaluationMetric', '') or '',
                'tags': tags_list,
                'dataset_files': dataset_info,
                'prize': int(getattr(competition, 'totalPrize', 0)) if getattr(competition, 'totalPrize', None) else 0,
                'participants': int(getattr(competition, 'totalTeams', 0)) if getattr(competition, 'totalTeams', None) else 0,
                'deadline': getattr(competition, 'deadline', '') or '',
            }
            
        except Exception as e:
            raise Exception(f"Failed to fetch project data: {str(e)}")
    
    def _perform_comprehensive_analysis(self, competition_data: Dict[str, Any], dataset_columns: List[str]) -> Dict[str, Any]:
        """Perform comprehensive competition analysis"""
        
        # Problem type detection - now returns structured dict
        problem_result = self.nlp_processor.detect_problem_type(competition_data)
        
        # Evaluation metric detection - now returns structured dict  
        metric_result = self.nlp_processor.detect_evaluation_metric(competition_data)
        
        # Target column detection - now returns structured dict
        target_result = self.nlp_processor.detect_target_column(
            competition_data, dataset_columns
        )
        
        # FIXED: Use enhanced UnifiedRecommendationSystem for consistency
        rec_sys = UnifiedRecommendationSystem()
        algorithm_recommendations = rec_sys.recommend(
            problem_type=problem_result['best_guess'],
            dataset=df if df is not None else None
        )
        
        # Validation strategy
        validation_strategy = self._determine_validation_strategy(problem_result['best_guess'], competition_data)
        
        # Preprocessing needs - now returns structured dict
        preprocessing_result = self.nlp_processor.detect_preprocessing_needs(competition_data, problem_result['best_guess'])
        
        # Enhanced strategy generation using AdvancedNLPProcessor
        combined_text = " ".join([
            str(competition_data.get('title', '')),
            str(competition_data.get('description', '')),
            str(competition_data.get('overview', ''))
        ])
        
        # Run advanced NLP analysis
        nlp_analysis = self.nlp_processor.process_text(combined_text)
        
        # Generate prioritized strategies
        strategies = map_to_strategies(nlp_analysis)
        
        return {
            'competition_data': competition_data,
            'problem_result': problem_result,
            'metric_result': metric_result,
            'target_result': target_result,
            'algorithm_recommendations': algorithm_recommendations,
            'validation_strategy': validation_strategy,
            'preprocessing_result': preprocessing_result,
            'nlp_analysis': nlp_analysis,
            'strategies': strategies
        }
    
    def _determine_validation_strategy(self, problem_type: str, competition_data: Dict[str, Any]) -> str:
        """Determine optimal validation strategy"""
        
        text_analysis = " ".join([
            competition_data.get('description', ''),
            competition_data.get('title', '')
        ]).lower()
        
        # Time series indicators
        time_indicators = ['time', 'temporal', 'sequence', 'forecast', 'trend', 'seasonal']
        if any(indicator in text_analysis for indicator in time_indicators):
            return "TimeSeriesSplit"
        
        # Problem type based
        if problem_type == 'classification':
            return "StratifiedKFold"
        elif problem_type == 'regression':
            return "KFold"
        else:
            return "KFold"
    
    def _format_json_response(self, analysis_results: Dict[str, Any]) -> Dict[str, Any]:
        """Format analysis results into structured JSON response"""
        
        # Extract results from structured responses
        problem_result = analysis_results['problem_result']
        metric_result = analysis_results['metric_result']
        target_result = analysis_results['target_result']
        preprocessing_result = analysis_results['preprocessing_result']
        nlp_analysis = analysis_results.get('nlp_analysis', {})
        strategies = analysis_results.get('strategies', [])
        
        # Build training strategy with improved preprocessing steps
        training_strategy = {
            'preprocessing_steps': [
                step for step, needed in preprocessing_result['recommended_steps'].items() 
                if needed
            ],
            'recommended_cv_folds': 5,
            'test_size': 0.2,
            'enable_early_stopping': True,
            'enable_regularization': True,
            'enable_ensemble': True,
            'problem_type_specific': preprocessing_result.get('problem_type_specific', False)
        }
        
        # Confidence-based notes with improved messaging
        notes = []
        if problem_result['confidence'] >= 0.8:
            notes.append("🟢 High confidence problem type detection")
            if problem_result.get('is_hybrid'):
                notes.append("🔄 Hybrid problem detected - consider multiple approaches")
        elif problem_result['confidence'] >= 0.6:
            notes.append("🟡 Moderate confidence - verify problem type")
        else:
            notes.append("🔴 Low confidence - manual review recommended")
        
        if target_result['confidence'] < 0.7:
            notes.append("⚠️ Target column detection uncertain - manual selection recommended")
        
        if metric_result['confidence'] < 0.5:
            notes.append("📊 Evaluation metric unclear - check competition details")
        
        # Main response structure with improved data access
        return {
            # Core predictions
            "competition_name": analysis_results['competition_data']['name'],
            "problem_type": problem_result['best_guess'],
            "problem_confidence": problem_result['confidence'],
            "problem_candidates": problem_result.get('candidates', {}),
            "is_hybrid_problem": problem_result.get('is_hybrid', False),
            
            "target_column": target_result['best_guess'],
            "target_confidence": target_result['confidence'],
            "target_candidates": target_result.get('candidates', {}),
            
            "evaluation_metric": metric_result['best_guess'],
            "metric_confidence": metric_result['confidence'],
            "metric_candidates": metric_result.get('candidates', {}),
            
            # Recommendations - FIXED: Use UnifiedRecommendationSystem consistently  
            "recommended_algorithms": self._get_unified_algorithm_recommendations(
                problem_result['best_guess'], 
                analysis_results.get('datasets', {})
            ),
            "validation_strategy": analysis_results['validation_strategy'],
            "training_strategy": training_strategy,
            
            # Additional insights
            "all_detected_metrics": metric_result.get('detected_metrics', []),
            "alternative_algorithms": self._get_unified_alternative_algorithms(
                problem_result['best_guess'], 
                analysis_results.get('datasets', {})
            ),
            "enhanced_insights": problem_result.get('enhanced_insights', []),
            "nlp_available": problem_result.get('nlp_available', False),
            "notes": notes,
            
            # Enhanced preprocessing insights
            "preprocessing_insights": {
                "problem_type_specific": preprocessing_result.get('problem_type_specific', False),
                "context_additions": preprocessing_result.get('context_based_additions', []),
                "recommended_steps": preprocessing_result['recommended_steps']
            },
            
            # Enhanced Strategy Recommendations
            "kaggle_strategies": strategies,
            "strategy_count": len(strategies),
            "high_priority_strategies": [s for s in strategies if s['priority'] == 'High'],
            
            # Advanced NLP Analysis Results
            "nlp_insights": nlp_analysis.get('insights_text', ''),
            "detected_domains": nlp_analysis.get('signals', {}),
            "domain_keywords": nlp_analysis.get('keywords', []),
            
            # Future extensibility (ready for later enhancements)
            "feature_engineering_suggestions": [],  # Future enhancement
            "data_leakage_warnings": [],           # Future enhancement
            "advanced_techniques": [],             # Future enhancement
            "ensemble_recommendations": [],        # Future enhancement
            "hyperparameter_suggestions": {},      # Future enhancement
            
            # Metadata
            "analysis_timestamp": pd.Timestamp.now().isoformat(),
            "analysis_quality": "Advanced" if ADVANCED_NLP_AVAILABLE else "Basic",
            "competition_metadata": {
                "title": analysis_results['competition_data']['title'],
                "participants": analysis_results['competition_data']['participants'],
                "prize": analysis_results['competition_data']['prize']
            }
        }
    
    def _error_response(self, error_message: str) -> Dict[str, Any]:
        """Return structured error response"""
        return {
            "error": True,
            "message": error_message,
            "problem_type": "unknown",
            "target_column": "unknown",
            "evaluation_metric": "unknown",
            "recommended_algorithms": UnifiedRecommendationSystem().recommend('classification')['recommended'][:3],
            "validation_strategy": "StratifiedKFold",
            "notes": [f"🔴 Analysis failed: {error_message}"],
            "analysis_timestamp": pd.Timestamp.now().isoformat()
        }
    
    def _normalize_problem_type(self, problem_type: str) -> str:
        """Normalize problem type for UnifiedRecommendationSystem compatibility"""
        if not problem_type:
            return 'classification'
            
        # Convert to lowercase and handle common mappings
        normalized = problem_type.lower().strip()
        
        # Handle underscore to space conversion for time series
        problem_type_mapping = {
            'time_series': 'time series',
            'timeseries': 'time series', 
            'forecasting': 'time series',
            'vision': 'image',
            'computer_vision': 'image',
            'cv': 'image',
            'nlp': 'text',
            'text_classification': 'text',
            'natural_language': 'text'
        }
        
        return problem_type_mapping.get(normalized, normalized)
    
    def _get_unified_algorithm_recommendations(self, problem_type: str, datasets: Dict = None) -> List[str]:
        """Get algorithm recommendations using UnifiedRecommendationSystem with dataset awareness"""
        try:
            # Create unified recommendation system instance
            unified_system = UnifiedRecommendationSystem()
            
            # Normalize problem type for compatibility
            normalized_problem_type = self._normalize_problem_type(problem_type)
            
            # Determine dataset characteristics for intelligent recommendations
            dataset_info = None
            if datasets and len(datasets) > 0:
                # Get the first available dataset for analysis
                first_dataset = next(iter(datasets.values()))
                if hasattr(first_dataset, 'shape'):
                    dataset_info = first_dataset
            
            # Get intelligent recommendations based on problem type and dataset
            recommendations = unified_system.recommend(normalized_problem_type, dataset=dataset_info)
            return recommendations['recommended']
            
        except Exception as e:
            # Fallback to basic recommendations if anything fails
            unified_system = UnifiedRecommendationSystem()
            fallback_recommendations = unified_system.recommend('classification')
            return fallback_recommendations['recommended'][:5]
    
    def _get_unified_alternative_algorithms(self, problem_type: str, datasets: Dict = None) -> List[str]:
        """Get alternative algorithm recommendations using UnifiedRecommendationSystem"""
        try:
            # Create unified recommendation system instance
            unified_system = UnifiedRecommendationSystem()
            
            # Normalize problem type for compatibility
            normalized_problem_type = self._normalize_problem_type(problem_type)
            
            # Determine dataset characteristics for intelligent recommendations
            dataset_info = None
            if datasets and len(datasets) > 0:
                # Get the first available dataset for analysis
                first_dataset = next(iter(datasets.values()))
                if hasattr(first_dataset, 'shape'):
                    dataset_info = first_dataset
            
            # Get intelligent recommendations and return alternatives
            recommendations = unified_system.recommend(normalized_problem_type, dataset=dataset_info)
            # Prefer explicit alternatives if available, otherwise use speed-optimized
            return recommendations.get('alternatives', recommendations.get('speed_optimized', recommendations['recommended'][3:8]))
            
        except Exception as e:
            # Fallback to basic alternatives if anything fails
            unified_system = UnifiedRecommendationSystem()
            fallback_recommendations = unified_system.recommend('classification')
            return fallback_recommendations['recommended'][3:6]

