    # Fallback to regex-based detection
    if not ADVANCED_NLP_AVAILABLE or not insights:
        text_to_analyze = problem_text.lower()
        if re.search(r'time series|forecast|trend', text_to_analyze):
            insights.append("Time-series problem detected: consider sequential models.")
        if re.search(r'image|photo|vision|object detection|segmentation', text_to_analyze):
            insights.append("Computer vision problem: consider CNNs and data augmentation.")
        if re.search(r'text|sentiment|nlp|document|tweet|review', text_to_analyze):
            insights.append("NLP problem detected: preprocessing and TF-IDF/Transformers may help.")
        if re.search(r'imbalance|rare event|fraud|churn|small class', text_to_analyze):
            insights.append("Imbalanced data detected: consider SMOTE or class-weight adjustments.")

    if not insights:
        insights.append("General problem detected: standard feature engineering and ML pipelines may suffice.")
    return insights

