if TORCH_AVAILABLE:
    class SimpleCNN(torch.nn.Module):
        def __init__(self, in_channels, num_classes, image_size=(28,28)):
            super().__init__()
            self.conv1 = torch.nn.Conv2d(in_channels, 16, 3, padding=1)
            self.relu = torch.nn.ReLU()
            self.pool = torch.nn.MaxPool2d(2)
            self.conv2 = torch.nn.Conv2d(16, 32, 3, padding=1)
            h, w = image_size
            self.flattened_size = 32 * (h//4) * (w//4)
            self.fc1 = torch.nn.Linear(self.flattened_size, 128)
            self.fc2 = torch.nn.Linear(128, num_classes)

        def forward(self, x):
            x = self.pool(self.relu(self.conv1(x)))
            x = self.pool(self.relu(self.conv2(x)))
            x = x.view(-1, self.flattened_size)
            x = self.relu(self.fc1(x))
            return self.fc2(x)
else:
    class SimpleCNN:
        def __init__(self, *args, **kwargs):
            raise ImportError("PyTorch not available - cannot use SimpleCNN")

if TORCH_AVAILABLE:
    class PyTorchClassifier:
        """Enhanced sklearn-style wrapper for PyTorch models."""
        def __init__(self, model, max_epochs=12, lr=0.001, batch_size=64):
            self.model = model
            self.max_epochs = max_epochs
            self.lr = lr
            self.batch_size = batch_size
            self.criterion = torch.nn.CrossEntropyLoss()
            self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
            self.model.to(self.device)
            self.optimizer = torch.optim.Adam(self.model.parameters(), lr=self.lr)

        def fit(self, X, y):
            X_tensor = torch.tensor(X, dtype=torch.float32).to(self.device)
            y_tensor = torch.tensor(y, dtype=torch.long).to(self.device)
            loader = torch.utils.data.DataLoader(torch.utils.data.TensorDataset(X_tensor, y_tensor), batch_size=self.batch_size, shuffle=True)
            self.model.train()
            for _ in range(self.max_epochs):
                for xb, yb in loader:
                    self.optimizer.zero_grad()
                    loss = self.criterion(self.model(xb), yb)
                    loss.backward()
                    self.optimizer.step()
            return self

        def predict(self, X):
            self.model.eval()
            X_tensor = torch.tensor(X, dtype=torch.float32).to(self.device)
            with torch.no_grad():
                outputs = self.model(X_tensor)
                _, pred = torch.max(outputs, 1)
            return pred.cpu().numpy()
else:
    class PyTorchClassifier:
        def __init__(self, *args, **kwargs):
            raise ImportError("PyTorch not available - cannot use PyTorchClassifier")

