class PyTorchClassifierWrapper:
    """
    Generic PyTorch model wrapper for classification
    """
    def __init__(self, model, max_epochs=10, lr=0.001, batch_size=32):
        self.model = model
        self.max_epochs = max_epochs
        self.lr = lr
        self.batch_size = batch_size
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        self.model.to(self.device)
        try:
            self.criterion = torch.nn.CrossEntropyLoss()
            self.optimizer = torch.optim.Adam(self.model.parameters(), lr=self.lr)
        except:
            pass  # Will be set during fit if torch available

    def fit(self, X, y):
        if not TORCH_AVAILABLE:
            raise ImportError("PyTorch not available")
        X_tensor = torch.tensor(X, dtype=torch.float32).to(self.device)
        y_tensor = torch.tensor(y, dtype=torch.long).to(self.device)
        dataset = torch.utils.data.TensorDataset(X_tensor, y_tensor)
        loader = torch.utils.data.DataLoader(dataset, batch_size=self.batch_size, shuffle=True)

        self.model.train()
        for _ in range(self.max_epochs):
            for xb, yb in loader:
                self.optimizer.zero_grad()
                out = self.model(xb)
                loss = self.criterion(out, yb)
                loss.backward()
                self.optimizer.step()
        return self

    def predict(self, X):
        if not TORCH_AVAILABLE:
            raise ImportError("PyTorch not available")
        self.model.eval()
        X_tensor = torch.tensor(X, dtype=torch.float32).to(self.device)
        with torch.no_grad():
            out = self.model(X_tensor)
            _, pred = torch.max(out, 1)
        return pred.cpu().numpy()

# Example simple LSTM model
class LSTMClassifier:
    def __init__(self, input_size, hidden_size, num_classes, num_layers=1):
        if not TORCH_AVAILABLE:
            return
        super(LSTMClassifier, self).__init__()
        self.lstm = torch.nn.LSTM(input_size, hidden_size, num_layers, batch_first=True)
        self.fc = torch.nn.Linear(hidden_size, num_classes)

    def forward(self, x):
        if not TORCH_AVAILABLE:
            return None
        out, _ = self.lstm(x)
        out = out[:, -1, :]  # take last time step
        out = self.fc(out)
        return out

