def get_hybrid_algorithms(problem_type="classification", data_type="structured", n_classes=None, image_shape=None, use_deep=False):
    """
    Hybrid algorithm selection with session state caching for consistency.
    Returns sklearn-compatible algorithms and external models.
    """
    cache_key = f"hybrid_algorithms_{problem_type}_{data_type}_{use_deep}"
    
    # Initialize session state cache if not exists
    if "algorithm_cache" not in st.session_state:
        st.session_state["algorithm_cache"] = {}

    # Return cached results if available
    if cache_key in st.session_state["algorithm_cache"]:
        return st.session_state["algorithm_cache"][cache_key]

    algorithms = {}
    external_models = {}

    # --- Structured Data ---
    if data_type == "structured":
        if problem_type == "classification":
            # Use class_weight='balanced' to handle class imbalance in financial data
            algorithms.update({
                "Random Forest": RandomForestClassifier(n_estimators=100, random_state=42, class_weight='balanced'),
                "Logistic Regression": LogisticRegression(max_iter=1000, class_weight='balanced'),
                "K-Nearest Neighbors": KNeighborsClassifier(),
                "Neural Network": MLPClassifier(hidden_layer_sizes=(100, 50), max_iter=300, random_state=42),
                "Autoencoder": MLPClassifier(hidden_layer_sizes=(50, 25, 50), max_iter=300, random_state=42),
            })
            if XGB_AVAILABLE:
                # scale_pos_weight will be auto-calculated during training for imbalanced data
                algorithms["XGBoost"] = xgb.XGBClassifier(random_state=42, eval_metric='logloss')
            if LGB_AVAILABLE:
                # class_weight='balanced' handles imbalance for LightGBM
                algorithms["LightGBM"] = lgb.LGBMClassifier(random_state=42, class_weight='balanced')
        else:
            algorithms.update({
                "Random Forest": RandomForestRegressor(n_estimators=100, random_state=42),
                "Linear Regression": LinearRegression(),
                "Ridge Regression": Ridge(),
                "Neural Network": MLPRegressor(hidden_layer_sizes=(100, 50), max_iter=300, random_state=42),
                "Autoencoder": MLPRegressor(hidden_layer_sizes=(50, 25, 50), max_iter=300, random_state=42),
            })
            if XGB_AVAILABLE:
                algorithms["XGBoost"] = xgb.XGBRegressor(random_state=42)
            if LGB_AVAILABLE:
                algorithms["LightGBM"] = lgb.LGBMRegressor(random_state=42)

    # 2. NLP
    elif data_type == "nlp":
        from sklearn.feature_extraction.text import TfidfVectorizer
        from sklearn.pipeline import Pipeline
        
        tfidf = TfidfVectorizer(max_features=10000, stop_words='english', ngram_range=(1,2))
        if problem_type == "classification":
            algorithms.update({
                "TF-IDF + Logistic Regression": Pipeline([('vectorizer', tfidf), ('classifier', LogisticRegression(max_iter=1000))]),
                "TF-IDF + SVC": Pipeline([('vectorizer', tfidf), ('classifier', SVC(probability=True, kernel='linear'))]),
                "TF-IDF + Naive Bayes": Pipeline([('vectorizer', tfidf), ('classifier', MultinomialNB())]),
                "TF-IDF + ML": Pipeline([('vectorizer', tfidf), ('classifier', LogisticRegression(max_iter=1000))])  # General option using best performer
            })
        else:
            algorithms.update({
                "TF-IDF + Linear Regression": Pipeline([('vectorizer', tfidf), ('regressor', LinearRegression())]),
                "TF-IDF + SVR": Pipeline([('vectorizer', tfidf), ('regressor', SVR())]),
                "TF-IDF + ML": Pipeline([('vectorizer', tfidf), ('regressor', LinearRegression())])  # General option using best performer
            })

    # 3. Computer Vision
    elif data_type == "computer_vision":
        if use_deep and TORCH_AVAILABLE:
            if n_classes is None or image_shape is None:
                raise ValueError("Deep learning for CV requires n_classes and image_shape")
            # PyTorch models would be defined locally or imported from separate module
            cnn_model = SimpleCNN(image_shape[0], n_classes, image_size=image_shape[1:])
            external_models["Deep CNN"] = PyTorchClassifier(cnn_model)
        else:
            if problem_type=="classification":
                algorithms.update({
                    "Random Forest": RandomForestClassifier(n_estimators=100),
                    "SVC (RBF)": SVC(probability=True, kernel='rbf'),
                    "MLPClassifier": MLPClassifier(hidden_layer_sizes=(512,256,128), max_iter=300)
                })
            else:
                algorithms.update({
                    "Random Forest": RandomForestRegressor(n_estimators=100),
                    "SVR": SVR(),
                    "MLPRegressor": MLPRegressor(hidden_layer_sizes=(512,256,128), max_iter=300)
                })

    # 4. Time Series & Forecasting
    elif data_type == "time_series":
        if problem_type=="classification":
            algorithms.update({
                "Random Forest": RandomForestClassifier(n_estimators=100),
                "Gradient Boosting": GradientBoostingClassifier(n_estimators=100)
            })
        else:
            algorithms.update({
                "Random Forest": RandomForestRegressor(n_estimators=100),
                "Gradient Boosting": GradientBoostingRegressor(n_estimators=100)
            })
            # ✅ TIME SERIES ADAPTERS - Now fully functional
            try:
                algorithms["ARIMA"] = ARIMAAdapter()
            except ImportError:
                pass
            try:
                algorithms["Prophet"] = ProphetAdapter()
            except ImportError:
                pass
            try:
                algorithms["Holt-Winters"] = HoltWintersAdapter()
            except ImportError:
                pass
            if TORCH_AVAILABLE:
                algorithms["LSTM Time Series"] = LSTMTSAdapter()

    # --- Computer Vision with Deep Learning ---
    if data_type == "computer_vision" and use_deep and TORCH_AVAILABLE:
        if n_classes is None or image_shape is None:
            raise ValueError("Deep learning CV requires n_classes and image_shape")
        cnn_model = SimpleCNN(image_shape[0], n_classes, image_size=image_shape[1:])
        external_models["Deep CNN"] = PyTorchClassifier(cnn_model)

    # --- External placeholders for advanced models ---
    if data_type in ["nlp", "time_series"]:
        external_models["LSTM"] = "LSTM placeholder"
        external_models["BERT"] = "BERT placeholder" 
        external_models["Transformer"] = "Transformer placeholder"

    # Cache results for consistency across UI components
    st.session_state["algorithm_cache"][cache_key] = (algorithms, external_models)
    return algorithms, external_models

