    def get_sample_dataframe(self, dataset):
        """Get sample DataFrame for analysis"""
        try:
            if hasattr(dataset, 'shape'):
                return dataset.head(1000)
            else:
                # Chunked iterator
                try:
                    first_chunk = next(iter(dataset))
                    return first_chunk.head(1000)
                except Exception:
                    return pd.DataFrame()
        except Exception:
            return pd.DataFrame()

    def load_file(self, file_obj, name):
        """Helper to load a dataset based on extension"""
        suffix = str(name).lower().split(".")[-1]
        if suffix == "csv":
            return pd.read_csv(file_obj)
        elif suffix in ["xlsx", "xls"]:
            return pd.read_excel(file_obj)
        elif suffix == "json":
            return pd.read_json(file_obj)
        elif suffix == "parquet":
            return pd.read_parquet(file_obj)
        elif suffix == "tsv":
            return pd.read_csv(file_obj, sep="\t")
        elif suffix == "txt":
            try:
                return pd.read_csv(file_obj)
            except Exception:
                return pd.read_csv(file_obj, sep="\t")
        else:
            raise ValueError(f"Unsupported file type: {suffix}")
    
