    def test_algorithms_with_realworld_data(self, problem_type: str = "classification", use_loaded_data: bool = True):
        """
        ENHANCED: Test multiple ML algorithms with real-world data or intelligent synthetic data.
        
        Parameters:
            problem_type (str): "classification", "regression", "nlp", "computer_vision", "time_series"
            use_loaded_data (bool): whether to use actual loaded dataset or fallback to synthetic
        
        Returns:
            pd.DataFrame with diagnostic results plus detection info
        """
        # pandas already imported globally
        import numpy as np
        
        # ENHANCED: Try to use real loaded data first if available
        if use_loaded_data and ENHANCED_DIAGNOSTICS_AVAILABLE and st.session_state.get("datasets"):
            try:
                # Get the first available dataset for testing
                dataset_names = list(st.session_state.datasets.keys())
                if dataset_names:
                    test_df = st.session_state.datasets[dataset_names[0]]
                    
                    # FIXED: Force the data type based on user selection
                    if problem_type == "nlp":
                        data_type_override = "nlp"
                    elif problem_type == "computer_vision":
                        data_type_override = "computer_vision" 
                    elif problem_type == "time_series":
                        data_type_override = "time_series"
                    else:
                        data_type_override = None  # Let auto-detection work
                    
                    # Custom diagnostic with user's manual override
                    if data_type_override:
                        st.info(f"🎯 **Manual Override**: Testing {data_type_override.replace('_', ' ').title()} algorithms on your data")
                        # Create custom results based on user selection
                        from tensorflow_free_diagnostic_pipeline import get_realworld_algorithms
                        
                        # Auto-detect target and prep data
                        from tensorflow_free_diagnostic_pipeline import detect_target_column, detect_problem_type
                        target_col = detect_target_column(test_df)
                        actual_problem_type = detect_problem_type(test_df, target_col)
                        
                        X = test_df.drop(columns=[target_col])
                        y = test_df[target_col]
                        
                        # Get algorithms based on user's selection
                        algorithms = get_realworld_algorithms(actual_problem_type, data_type_override)
                        
                        results = []
                        # Test each algorithm
                        for name, algorithm in algorithms.items():
                            try:
                                # Skip string placeholders 
                                if isinstance(algorithm, str):
                                    results.append({
                                        "algorithm": name,
                                        "fit_status": "🔄",
                                        "predict_status": "🔄",
                                        "predict_proba_status": "🔄",
                                        "validation_score": "Pending",
                                        "error": "Algorithm implementation pending"
                                    })
                                    continue
                                
                                from sklearn.model_selection import train_test_split
                                
                                # Handle different data preprocessing for different types
                                if data_type_override == "nlp":
                                    # For NLP, use text columns as-is (pipeline handles vectorization)
                                    X_processed = X
                                elif data_type_override == "computer_vision":
                                    # For CV, ensure numeric data and proper scaling
                                    X_processed = X.select_dtypes(include=[np.number]).fillna(0)
                                    if X_processed.empty:
                                        # If no numeric columns, treat as structured
                                        X_processed = pd.get_dummies(X).fillna(0)
                                elif data_type_override == "time_series":
                                    # For time series, create basic lag features
                                    X_processed = X.select_dtypes(include=[np.number]).fillna(method='ffill').fillna(0)
                                else:
                                    X_processed = X
                                
                                X_train, X_val, y_train, y_val = train_test_split(X_processed, y, test_size=0.2, random_state=42)
                                algorithm.fit(X_train, y_train)
                                score = algorithm.score(X_val, y_val)
                                
                                # Test predict_proba if available
                                proba_status = "N/A"
                                if hasattr(algorithm, "predict_proba") and actual_problem_type == "classification":
                                    try:
                                        algorithm.predict_proba(X_val)
                                        proba_status = "✅"
                                    except:
                                        proba_status = "❌"
                                elif actual_problem_type == "classification":
                                    proba_status = "❌"
                                
                                results.append({
                                    "algorithm": name,
                                    "fit_status": "✅",
                                    "predict_status": "✅", 
                                    "predict_proba_status": proba_status,
                                    "validation_score": f"{score:.3f}",
                                    "error": ""
                                })
                            except Exception as e:
                                results.append({
                                    "algorithm": name,
                                    "fit_status": "❌",
                                    "predict_status": "❌",
                                    "predict_proba_status": "❌",
                                    "validation_score": "N/A",
                                    "error": str(e)[:100]
                                })
                        
                        # Display results
                        col1, col2, col3, col4 = st.columns(4)
                        with col1:
                            st.metric("Target Column", target_col)
                        with col2:
                            st.metric("Problem Type", actual_problem_type.title())
                        with col3:
                            st.metric("Data Type", data_type_override.replace('_', ' ').title())
                        with col4:
                            st.metric("Dataset Size", f"{X.shape[0]} × {X.shape[1]}")
                        
                        return pd.DataFrame(results)
                    else:
                        # Use fully automated detection
                        diagnostic_results = run_automated_realworld_diagnostic(test_df)
                        
                        # Display detection info
                        detection_info = get_detection_summary(diagnostic_results)
                        st.success("🎯 **Real-World Data Analysis Complete!**")
                        
                        col1, col2, col3, col4 = st.columns(4)
                        with col1:
                            st.metric("Target Column", detection_info['Target Column'])
                        with col2:
                            st.metric("Problem Type", detection_info['Problem Type'])
                        with col3:
                            st.metric("Data Type", detection_info['Data Type'])
                        with col4:
                            st.metric("Dataset Size", detection_info['Dataset Shape'])
                        
                        # Show recommendations
                        if diagnostic_results.get('recommendations'):
                            st.info("📊 **Automated Analysis**: " + "; ".join(diagnostic_results['recommendations'][:2]))
                        
                        # Return formatted results
                        return format_results_for_streamlit(diagnostic_results)
                    
            except Exception as e:
                st.warning(f"⚠️ Could not analyze real data ({str(e)[:100]}...), using synthetic testing")
        
        # FALLBACK: Use ENHANCED SYNTHETIC DATA with specialized algorithms
        from sklearn.datasets import make_classification, make_regression
        
        st.info("🔬 **Enhanced Synthetic Testing**: Using specialized algorithms with simulated data")
        
        sample_size = 200
        
        # Generate synthetic data and determine data type
        if problem_type == "classification":
            X, y = make_classification(
                n_samples=sample_size, n_features=10, n_informative=5, 
                n_classes=2, random_state=42
            )
            detected_problem_type = "classification"
        elif problem_type == "regression":
            X, y = make_regression(
                n_samples=sample_size, n_features=10, n_informative=5, 
                noise=0.1, random_state=42
            )
            detected_problem_type = "regression"
        elif problem_type == "nlp":
            # Simulate text-like features
            np.random.seed(42)
            X = np.random.randint(0, 100, (sample_size, 50))  # Vocabulary features
            y = np.random.randint(0, 2, sample_size)  # Binary classification
            detected_problem_type = "classification"  # NLP is typically classification
        elif problem_type == "computer_vision":
            # Simulate image-like features
            np.random.seed(42)
            X = np.random.rand(sample_size, 784)  # 28x28 image flattened
            y = np.random.randint(0, 10, sample_size)  # 10 classes
            detected_problem_type = "classification"  # CV is typically classification
        elif problem_type == "time_series":
            # Generate time series data
            np.random.seed(42)
            X = np.arange(sample_size).reshape(-1, 1)
            y = np.sin(0.1 * X.ravel()) + 0.1 * X.ravel() + np.random.normal(0, 0.1, sample_size)
            detected_problem_type = "time_series"  # Keep as time_series
        else:
            # Default to classification
            X, y = make_classification(
                n_samples=sample_size, n_features=10, n_informative=5, 
                n_classes=2, random_state=42
            )
            detected_problem_type = "classification"
        
        # Use ENHANCED DIAGNOSTICS with synthetic data
        results = run_enhanced_diagnostics(X, y, problem_type, detected_problem_type)
        
        st.success("🎯 **Enhanced Synthetic Analysis Complete!**")
        
        col1, col2, col3, col4 = st.columns(4)
        with col1:
            st.metric("Data Type", problem_type.replace('_', ' ').title())
        with col2:
            st.metric("Problem Type", detected_problem_type.title())
        with col3:
            st.metric("Dataset Size", f"{X.shape[0]} × {X.shape[1]}")
        with col4:
            successful_tests = sum(1 for result in results if result['fit_status'] == '✅')
            total_tests = len(results)
            success_rate = (successful_tests / total_tests * 100) if total_tests > 0 else 0
            st.metric("Success Rate", f"{success_rate:.1f}%")
        
        st.info(f"📊 **Enhanced Synthetic Results**: {successful_tests}/{total_tests} specialized algorithms successful")
        
        return pd.DataFrame(results)
    
    def _handle_image_training(self):
        """Handle PyTorch image training workflow"""
        st.header("🖼️ Advanced Image Training with PyTorch")
        
        if not TORCH_AVAILABLE:
            st.error("⚠️ PyTorch not available. Image training requires PyTorch installation.")
            st.info("Install PyTorch with: `pip install torch torchvision`")
            return
            
        if not PIL_AVAILABLE:
            st.error("⚠️ Pillow not available. Image processing requires Pillow installation.")
            st.info("Install Pillow with: `pip install Pillow`")
            return
            
        image_datasets = st.session_state.get('image_datasets', {})
        if not image_datasets:
            st.warning("⚠️ No image datasets found. Please upload image ZIP files first.")
            return
            
        # Dataset selection
        st.subheader("📊 Select Image Dataset")
        dataset_names = list(image_datasets.keys())
        selected_dataset = st.selectbox("Choose image dataset:", dataset_names, key="image_dataset_selector")
        
        if not selected_dataset:
            return
            
        img_data = image_datasets[selected_dataset]
        images = img_data['images']
        labels = img_data['labels']
        unique_labels = img_data['unique_labels']
        image_size = img_data['image_size']
        
        st.success(f"🎯 Selected: **{selected_dataset}** - {len(images)} images, {len(unique_labels)} classes")
        
        # Display class distribution
        col1, col2 = st.columns(2)
        with col1:
            st.markdown("**📊 Class Distribution:**")
            label_counts = pd.Series(labels).value_counts()
            st.bar_chart(label_counts)
        
        with col2:
            st.markdown("**🏷️ Classes:**")
