    def _train_image_model(self, images, labels, unique_labels, image_size, hyperparams):
        """Train PyTorch image model with comprehensive hyperparameters"""
        if not TORCH_AVAILABLE:
            raise RuntimeError("PyTorch not available")
            
        # Extract hyperparameters
        model_type = hyperparams['model_type']
        epochs = hyperparams['epochs']
        batch_size = hyperparams['batch_size']
        learning_rate = hyperparams['learning_rate']
        train_split = hyperparams['train_split']
        use_augmentation = hyperparams['use_augmentation']
        optimizer_type = hyperparams['optimizer_type']
        weight_decay = hyperparams['weight_decay']
        early_stopping = hyperparams['early_stopping']
        lr_scheduler = hyperparams['lr_scheduler']
        
        # Prepare labels
        label_to_int = {label: i for i, label in enumerate(unique_labels)}
        int_labels = [label_to_int[label] for label in labels]
        
        # Split data
        from sklearn.model_selection import train_test_split
        train_images, val_images, train_labels, val_labels = train_test_split(
            images, int_labels, train_size=train_split, random_state=42, stratify=int_labels
        )
        
        # Enhanced data augmentation based on user settings
        train_transform_list = []
        if use_augmentation:
            if hyperparams.get('rotation_angle', 0) > 0:
                train_transform_list.append(transforms.RandomRotation(hyperparams['rotation_angle']))
            if hyperparams.get('horizontal_flip', False):
                train_transform_list.append(transforms.RandomHorizontalFlip())
            if hyperparams.get('vertical_flip', False):
                train_transform_list.append(transforms.RandomVerticalFlip())
            
            # Color jitter
            brightness = hyperparams.get('brightness', 0)
            contrast = hyperparams.get('contrast', 0)
            saturation = hyperparams.get('saturation', 0)
            if brightness > 0 or contrast > 0 or saturation > 0:
                train_transform_list.append(
                    transforms.ColorJitter(brightness=brightness, contrast=contrast, saturation=saturation)
                )
        
        train_transform_list.append(transforms.ToTensor())
        
        # Normalization
        if hyperparams.get('normalize_data', True):
            train_transform_list.append(transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]))
        
        train_transform = transforms.Compose(train_transform_list)
        
        # Validation transform (no augmentation)
        val_transform_list = [transforms.ToTensor()]
        if hyperparams.get('normalize_data', True):
            val_transform_list.append(transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]))
        val_transform = transforms.Compose(val_transform_list)
        
        # Create datasets and loaders
        train_dataset = ImageFolderDataset(train_images, train_labels, train_transform)
        val_dataset = ImageFolderDataset(val_images, val_labels, val_transform)
        
        train_loader = DataLoader(train_dataset, batch_size=batch_size, shuffle=True)
        val_loader = DataLoader(val_dataset, batch_size=batch_size, shuffle=False)
        
        # Create model with architecture-specific parameters
        num_classes = len(unique_labels)
        device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        
        if model_type == "SimpleCNN":
            conv_channels = tuple(hyperparams.get('conv_channels', [16, 32, 64]))
            dropout_rate = hyperparams.get('dropout_rate', 0.2)
            model = DynamicSimpleCNN(
                in_channels=3,
                conv_channels=conv_channels,
                num_classes=num_classes,
                image_size=image_size,
                dropout=dropout_rate
            )
        elif model_type == "ResNet18":
            pretrained = hyperparams.get('use_pretrained', False)
            model = get_resnet_model(num_classes=num_classes, pretrained=pretrained)
            
            # Freeze backbone if requested
            if hyperparams.get('freeze_backbone', False):
                for param in model.parameters():
                    param.requires_grad = False
                # Unfreeze the final layer
                for param in model.fc.parameters():
                    param.requires_grad = True
                    
        elif model_type == "EfficientNet-B0":
            version = hyperparams.get('efficientnet_version', 'b0')
            pretrained = hyperparams.get('use_pretrained', False)
            model = get_efficientnet_model(num_classes=num_classes, version=version, pretrained=pretrained)
        else:
            raise ValueError(f"Unknown model type: {model_type}")
        
        model.to(device)
        
        # Enhanced optimizer setup
        if optimizer_type == "Adam":
            optimizer = optim.Adam(model.parameters(), lr=learning_rate, weight_decay=weight_decay)
        elif optimizer_type == "SGD":
            momentum = hyperparams.get('momentum', 0.9)
            optimizer = optim.SGD(model.parameters(), lr=learning_rate, momentum=momentum, weight_decay=weight_decay)
        elif optimizer_type == "AdamW":
            optimizer = optim.AdamW(model.parameters(), lr=learning_rate, weight_decay=weight_decay)
        elif optimizer_type == "RMSprop":
            optimizer = optim.RMSprop(model.parameters(), lr=learning_rate, weight_decay=weight_decay)
        else:
            optimizer = optim.Adam(model.parameters(), lr=learning_rate, weight_decay=weight_decay)
        
        # Learning rate scheduler
        scheduler = None
        if lr_scheduler == "StepLR":
            step_size = hyperparams.get('step_size', 10)
            gamma = hyperparams.get('gamma', 0.1)
            scheduler = optim.lr_scheduler.StepLR(optimizer, step_size=step_size, gamma=gamma)
        elif lr_scheduler == "CosineAnnealingLR":
            scheduler = optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=epochs)
        elif lr_scheduler == "ReduceLROnPlateau":
            scheduler = optim.lr_scheduler.ReduceLROnPlateau(optimizer, mode='min', patience=5, factor=0.5)
        
        # Enhanced training with early stopping
        criterion = nn.CrossEntropyLoss()
        history = {'train_loss': [], 'train_acc': [], 'val_loss': [], 'val_acc': []}
        
        best_val_acc = 0.0
        patience_counter = 0
        patience = hyperparams.get('patience', 5) if early_stopping else epochs
        
        progress = st.progress(0)
        status_text = st.empty()
        
        for epoch in range(epochs):
            # Training phase
            model.train()
            running_loss = 0.0
            correct = 0
            total = 0
            
            for inputs, targets in train_loader:
                inputs, targets = inputs.to(device), targets.to(device)
                
                optimizer.zero_grad()
                outputs = model(inputs)
                loss = criterion(outputs, targets)
                loss.backward()
                optimizer.step()
                
                running_loss += loss.item() * inputs.size(0)
                _, predicted = torch.max(outputs.data, 1)
                total += targets.size(0)
                correct += (predicted == targets).sum().item()
            
            train_loss = running_loss / total
            train_acc = correct / total
            history['train_loss'].append(train_loss)
            history['train_acc'].append(train_acc)
            
            # Validation phase
            model.eval()
            val_loss = 0.0
            val_correct = 0
            val_total = 0
            
            with torch.no_grad():
                for inputs, targets in val_loader:
                    inputs, targets = inputs.to(device), targets.to(device)
                    outputs = model(inputs)
                    loss = criterion(outputs, targets)
                    
                    val_loss += loss.item() * inputs.size(0)
                    _, predicted = torch.max(outputs.data, 1)
                    val_total += targets.size(0)
                    val_correct += (predicted == targets).sum().item()
            
            val_loss /= val_total
            val_acc = val_correct / val_total
            history['val_loss'].append(val_loss)
            history['val_acc'].append(val_acc)
            
            # Learning rate scheduling
            if scheduler:
                if isinstance(scheduler, optim.lr_scheduler.ReduceLROnPlateau):
                    scheduler.step(val_loss)
                else:
                    scheduler.step()
            
            # Progress update
            status_text.text(f"Epoch {epoch+1}/{epochs} — Train: {train_acc:.3f} | Val: {val_acc:.3f} | LR: {optimizer.param_groups[0]['lr']:.6f}")
            progress.progress((epoch + 1) / epochs)
            
            # Early stopping
            if early_stopping:
                if val_acc > best_val_acc:
                    best_val_acc = val_acc
                    patience_counter = 0
                else:
                    patience_counter += 1
                    
                if patience_counter >= patience:
                    st.info(f"Early stopping triggered at epoch {epoch+1}")
                    break
        
        # Return comprehensive results
        return {
            'model': model,
            'history': history,
            'final_train_acc': history['train_acc'][-1] if history['train_acc'] else 0,
            'final_val_acc': history['val_acc'][-1] if history['val_acc'] else 0,
            'best_val_acc': best_val_acc,
            'model_type': model_type,
            'num_classes': num_classes,
            'unique_labels': unique_labels,
            'device': str(device),
            'hyperparams': hyperparams
        }

