            for dataset_name in selected_datasets:
                df = st.session_state.datasets[dataset_name]
                
                # Apply sampling if needed
                if use_sampling and len(df) > 1000:
                    # Proportional sampling based on dataset size
                    sample_fraction = min(1.0, MAX_SAFE_ROWS / total_rows)
                    sample_size = int(len(df) * sample_fraction)
                    df = df.sample(n=sample_size, random_state=42)
                
                combined_dfs.append(df)
            
            train_df = pd.concat(combined_dfs, ignore_index=True)
