    def generate_kaggle_notebook(self, results, X_train, y_train, X_test, y_test, problem_type):
        """Generate Platform notebook format (JSON) for competition submission - PROPER 3-STEP WORKFLOW
        
        Step 1: Internal validation already done during training (80/20 split)
        Step 2: Final training on FULL train.csv (this notebook)
        Step 3: Generate predictions on unseen test.csv
        """
        import json
        
        # Find best model
        # Guard against empty successful_models
        successful_models = {k: v for k, v in results.items() if v is not None and not isinstance(v, str)}
        
        if not successful_models:
            st.warning("No models trained successfully - cannot generate notebook")
            return None
        
        if problem_type == 'regression':
            best_model = max(successful_models.keys(), 
                           key=lambda x: successful_models[x].get('test_r2', 0))
            best_score = successful_models[best_model].get('test_r2', 0)
            best_rmse = successful_models[best_model].get('test_rmse', 0)
        else:
            # For classification, prioritize AUC over accuracy
            best_model = max(successful_models.keys(), 
                           key=lambda x: successful_models[x].get('test_auc', successful_models[x].get('test_accuracy', 0)))
            best_score = successful_models[best_model].get('test_accuracy', 0)
            best_auc = successful_models[best_model].get('test_auc', 0)
            best_f1 = successful_models[best_model].get('test_f1', 0)
            best_cv = successful_models[best_model].get('cv_mean', 0)
        
        # Get configuration from session state
        target_column = st.session_state.get('manual_target_column', 'market_forward_excess_returns')
        leaky_cols = st.session_state.get('leaky_columns_used', ['forward_returns', 'risk_free_rate'])
        ts_config = st.session_state.get('ts_feature_config', {})
        lag_periods = ts_config.get('lag_periods', [1, 7, 14, 30, 60, 90, 180, 360])
        rolling_windows = ts_config.get('rolling_windows', [7, 30, 60])
        skew_windows = ts_config.get('skew_windows', [30])
        
        # Get comprehensive metrics for notebook header
        best_m = successful_models.get(best_model, {})
        ic_val = best_m.get('information_coefficient', best_m.get('ic', None))
        sharpe_val = best_m.get('sharpe_of_signal', best_m.get('sharpe', None))
        dir_acc_val = best_m.get('directional_accuracy', None)
        cv_val = best_m.get('cv_mean', None)
        rank_ic_val = best_m.get('rank_ic', None)
        
        # Format metrics
        ic_s = f"{ic_val:.4f}" if ic_val is not None else "N/A"
        sharpe_s = f"{sharpe_val:.2f}" if sharpe_val is not None else "N/A"
        dir_s = f"{dir_acc_val:.2%}" if dir_acc_val is not None else "N/A"
        cv_s = f"{cv_val:.4f}" if cv_val is not None else "N/A"
