# pandas already imported globally
import numpy as np
from sklearn.preprocessing import StandardScaler
import warnings
warnings.filterwarnings('ignore')
{model_imports}

# Load data
train_df = pd.read_csv('train.csv')
test_df = pd.read_csv('test.csv')

print(f'Training shape: {{train_df.shape}}')
print(f'Test shape: {{test_df.shape}}')

# 🚀 PHASE 2: Advanced Time Series Feature Engineering
target_column = 'market_forward_excess_returns'
X_train = train_df.drop(columns=[target_column])
y_train = train_df[target_column]
X_test = test_df.drop(columns=[target_column], errors='ignore')

print(f'Original features: {{X_train.shape[1]}}')

# Get numeric columns for feature engineering
numeric_cols = X_train.select_dtypes(include=[np.number]).columns.tolist()

# 📈 Add lag features (1, 7, 14, 30, 60, 90, 180, 360 days)
for col in numeric_cols:
    for lag in [1, 7, 14, 30, 60, 90, 180, 360]:
        X_train[f'{{col}}_lag_{{lag}}'] = X_train[col].shift(lag)
        X_test[f'{{col}}_lag_{{lag}}'] = X_test[col].shift(lag)

# 📊 Add rolling statistics (mean, std, min, max)
for col in numeric_cols:
    for window in [7, 30, 60]:
        X_train[f'{{col}}_rolling_mean_{{window}}'] = X_train[col].shift(1).rolling(window, min_periods=1).mean()
        X_train[f'{{col}}_rolling_std_{{window}}'] = X_train[col].shift(1).rolling(window, min_periods=1).std()
        X_test[f'{{col}}_rolling_mean_{{window}}'] = X_test[col].shift(1).rolling(window, min_periods=1).mean()
        X_test[f'{{col}}_rolling_std_{{window}}'] = X_test[col].shift(1).rolling(window, min_periods=1).std()

# 📈 Add rolling skewness & kurtosis (30-day window)
for col in numeric_cols:
    X_train[f'{{col}}_rolling_skew_30'] = X_train[col].shift(1).rolling(30, min_periods=1).skew()
    X_train[f'{{col}}_rolling_kurt_30'] = X_train[col].shift(1).rolling(30, min_periods=1).kurt()
    X_test[f'{{col}}_rolling_skew_30'] = X_test[col].shift(1).rolling(30, min_periods=1).skew()
    X_test[f'{{col}}_rolling_kurt_30'] = X_test[col].shift(1).rolling(30, min_periods=1).kurt()

# CRITICAL: Calculate train median BEFORE filling to avoid subtle leakage
# The median must be computed on the ORIGINAL X_train, not the filled version
train_median = X_train.median()  # Save the imputation vector
X_train = X_train.fillna(train_median)  # Fill train with original median
X_test = X_test.fillna(train_median)  # Fill test with SAME train median

print(f'Enhanced features: {{X_train.shape[1]}} (added {{X_train.shape[1] - len(numeric_cols)}} Phase 2 features)')

# Preprocessing - fit scaler on TRAINING data only
scaler = StandardScaler()
X_train_scaled = scaler.fit_transform(X_train)
X_test_scaled = scaler.transform(X_test)

# ✅ Train {model_name} Model
print('🏆 Training {model_name}...')
{model_training}

# Generate predictions on test set
print('📊 Generating predictions on test data...')
y_pred = model.predict(X_test_scaled)

# Create submission
submission = pd.DataFrame()
submission['id'] = test_df['id'] if 'id' in test_df.columns else range(len(test_df))
