    def render_overfitting_analysis(self, successful_models):
        """Comprehensive overfitting analysis"""
        st.markdown("### 🔍 Overfitting & Underfitting Analysis")
        
        if not successful_models:
            st.warning("No successful models to analyze")
            return
        
        for model_name, metrics in successful_models.items():
            with st.expander(f"📊 {model_name} - Detailed Analysis"):
                col1, col2, col3 = st.columns(3)
                
                with col1:
                    st.markdown("**Performance Gap Analysis:**")
                    overfitting_gap = metrics.get('overfitting_gap', 0)
                    
                    if st.session_state.get('problem_type', 'regression') == 'classification':
                        train_acc = metrics.get('train_accuracy', 0)
                        test_acc = metrics.get('test_accuracy', 0)
                        st.write(f"Training Accuracy: {train_acc:.4f}")
                        st.write(f"Test Accuracy: {test_acc:.4f}")
                        st.write(f"Performance Gap: {overfitting_gap:.4f}")
                        
                        # Overfitting assessment
                        if overfitting_gap < 0.02:
                            st.success("🟢 Excellent generalization")
                        elif overfitting_gap < 0.05:
                            st.info("🔵 Good generalization")
                        elif overfitting_gap < 0.10:
                            st.warning("🟡 Moderate overfitting risk")
                        else:
                            st.error("🔴 High overfitting risk")
                    
                    else:  # regression
                        train_r2 = metrics.get('train_r2', 0)
                        test_r2 = metrics.get('test_r2', 0)
                        st.write(f"Training R²: {train_r2:.4f}")
                        st.write(f"Test R²: {test_r2:.4f}")
                        st.write(f"Performance Gap: {overfitting_gap:.4f}")
                        
                        if overfitting_gap < 0.05:
                            st.success("🟢 Excellent generalization")
                        elif overfitting_gap < 0.10:
                            st.info("🔵 Good generalization")
                        elif overfitting_gap < 0.20:
                            st.warning("🟡 Moderate overfitting risk")
                        else:
                            st.error("🔴 High overfitting risk")
                
                with col2:
                    st.markdown("**Cross-Validation Consistency:**")
                    cv_mean = metrics.get('cv_mean', 0)
                    cv_std = metrics.get('cv_std', 0)
                    
                    if st.session_state.get('problem_type', 'regression') == 'classification':
                        st.write(f"CV Mean Accuracy: {cv_mean:.4f}")
                    else:
                        st.write(f"CV Mean Score: {abs(cv_mean):.4f}")
                    
                    st.write(f"CV Std Deviation: {cv_std:.4f}")
                    
                    # Stability assessment
                    if cv_std < 0.02:
                        st.success("🟢 Very stable")
                    elif cv_std < 0.05:
                        st.info("🔵 Stable")
                    elif cv_std < 0.10:
                        st.warning("🟡 Moderately stable")
                    else:
                        st.error("🔴 Unstable predictions")
                
                with col3:
                    st.markdown("**Project Readiness Score:**")
                    
                    # Calculate comprehensive readiness score
                    readiness_score = self.calculate_kaggle_readiness(metrics)
                    
                    if readiness_score >= 85:
                        st.success(f"🏆 Excellent: {readiness_score:.0f}/100")
                        st.write("Ready for Platform submission")
                    elif readiness_score >= 70:
                        st.info(f"🥈 Good: {readiness_score:.0f}/100")
                        st.write("Likely to perform well")
                    elif readiness_score >= 50:
                        st.warning(f"🥉 Fair: {readiness_score:.0f}/100")
                        st.write("May need improvement")
                    else:
                        st.error(f"❌ Poor: {readiness_score:.0f}/100")
                        st.write("Needs significant improvement")
    
    def render_cv_stability_analysis(self, successful_models):
        """Cross-validation stability analysis"""
        st.markdown("### 📊 Cross-Validation Stability Analysis")
        
        if not successful_models:
            st.warning("No successful models to analyze")
            return
        
        stability_data = []
        
        for model_name, metrics in successful_models.items():
            cv_scores = metrics.get('cv_scores', [])
            if len(cv_scores) > 0:
                cv_mean = metrics.get('cv_mean', 0)
                cv_std = metrics.get('cv_std', 0)
                cv_min = min(cv_scores)
                cv_max = max(cv_scores)
                cv_range = cv_max - cv_min
                
                stability_data.append({
                    'Model': model_name,
                    'CV Mean': f"{abs(cv_mean):.4f}",
                    'CV Std': f"{cv_std:.4f}",
                    'CV Range': f"{cv_range:.4f}",
                    'Stability': 'High' if cv_std < 0.02 else 'Medium' if cv_std < 0.05 else 'Low'
                })
        
        if stability_data:
            stability_df = pd.DataFrame(stability_data)
            st.dataframe(stability_df, use_container_width=True)
            
            st.markdown("**Stability Guidelines:**")
            st.write("- **High Stability (CV Std < 0.02)**: Excellent for Platform - consistent performance across folds")
            st.write("- **Medium Stability (CV Std < 0.05)**: Good for Platform - minor variations expected")
            st.write("- **Low Stability (CV Std > 0.05)**: Risky for Platform - may have inconsistent leaderboard performance")
    
    def render_bias_variance_analysis(self, successful_models):
        """Bias-variance decomposition analysis"""
        st.markdown("### ⚖️ Bias-Variance Assessment")
        
        st.info("**Understanding Bias-Variance for Platform Success:**")
        st.write("- **High Bias (Underfitting)**: Poor performance on both training and test data")
        st.write("- **High Variance (Overfitting)**: Good training performance but poor test performance")
        st.write("- **Optimal Balance**: Good performance on both with small gap")
        
        if not successful_models:
            st.warning("No successful models to analyze")
            return
        
        bias_variance_data = []
        
        for model_name, metrics in successful_models.items():
            if st.session_state.get('problem_type', 'regression') == 'classification':
                train_perf = metrics.get('train_accuracy', 0)
                test_perf = metrics.get('test_accuracy', 0)
                baseline = 0.5  # Random baseline for classification
            else:
                train_perf = metrics.get('train_r2', 0)
                test_perf = metrics.get('test_r2', 0)
                baseline = 0.0  # Baseline for R²
            
            # Bias assessment (distance from optimal performance)
            bias_indicator = 1 - max(train_perf, test_perf)
            
            # Variance assessment (training vs test gap)
            variance_indicator = abs(train_perf - test_perf)
            
            # Overall assessment
            if bias_indicator > 0.3:
                bias_level = "High (Underfitting)"
                recommendation = "Increase model complexity"
            elif bias_indicator > 0.15:
                bias_level = "Medium"
                recommendation = "Moderate complexity"
            else:
                bias_level = "Low"
                recommendation = "Good model complexity"
            
            if variance_indicator > 0.1:
                variance_level = "High (Overfitting)"
                variance_rec = "Reduce complexity/Add regularization"
            elif variance_indicator > 0.05:
                variance_level = "Medium"
                variance_rec = "Monitor closely"
            else:
                variance_level = "Low"
                variance_rec = "Good generalization"
            
            bias_variance_data.append({
                'Model': model_name,
                'Train Performance': f"{train_perf:.4f}",
                'Test Performance': f"{test_perf:.4f}",
                'Bias Level': bias_level,
                'Variance Level': variance_level,
                'Recommendation': f"{recommendation}; {variance_rec}"
            })
        
        if bias_variance_data:
            bv_df = pd.DataFrame(bias_variance_data)
            st.dataframe(bv_df, use_container_width=True)
    
    def render_real_world_readiness(self, successful_models):
        """Real-world Platform performance readiness"""
        st.markdown("### 🌍 Real-World Platform Performance Readiness")
        
        st.info("**Key factors for Platform success beyond local validation:**")
        
        col1, col2 = st.columns(2)
        
        with col1:
            st.markdown("**✅ Positive Indicators:**")
            st.write("- Consistent CV scores across folds")
            st.write("- Small train-test performance gap")
            st.write("- Stable predictions on different data splits")
            st.write("- Robust feature preprocessing")
            st.write("- Conservative hyperparameter selection")
        
        with col2:
            st.markdown("**⚠️ Risk Factors:**")
            st.write("- High CV standard deviation")
            st.write("- Large overfitting gap")
            st.write("- Aggressive hyperparameter tuning")
            st.write("- Feature leakage potential")
            st.write("- Distribution shifts in test data")
        
        if successful_models:
            st.markdown("### 🏆 Model Recommendations for Platform")
            
            # Rank models by Platform readiness
            model_rankings = []
            for model_name, metrics in successful_models.items():
                readiness_score = self.calculate_kaggle_readiness(metrics)
                model_rankings.append((model_name, readiness_score, metrics))
            
            # Sort by readiness score
            model_rankings.sort(key=lambda x: x[1], reverse=True)
            
            for i, (model_name, score, metrics) in enumerate(model_rankings):
                if i == 0:
                    st.success(f"🥇 **Best Choice**: {model_name} (Readiness: {score:.0f}/100)")
                elif i == 1:
                    st.info(f"🥈 **Good Alternative**: {model_name} (Readiness: {score:.0f}/100)")
                else:
                    st.write(f"🥉 **Option {i+1}**: {model_name} (Readiness: {score:.0f}/100)")
                
                # Specific recommendations
                overfitting_gap = metrics.get('overfitting_gap', 0)
                cv_std = metrics.get('cv_std', 0)
                
                recommendations = []
                if overfitting_gap > 0.05:
                    recommendations.append("Consider regularization or ensemble methods")
                if cv_std > 0.05:
                    recommendations.append("Model may be unstable - use ensemble or more conservative parameters")
                if not recommendations:
                    recommendations.append("Model appears ready for Platform submission")
                
                st.write(f"   💡 Recommendation: {'; '.join(recommendations)}")
        
        st.markdown("### 🎯 Additional Strategies for Platform Success")
        
