    def calculate_kaggle_readiness(self, metrics):
        """Calculate a comprehensive Platform readiness score"""
        score = 0
        
        # Performance component (40%)
        if st.session_state.get('problem_type', 'regression') == 'classification':
            test_perf = metrics.get('test_accuracy', 0)
            if test_perf > 0.9:
                score += 40
            elif test_perf > 0.8:
                score += 30
            elif test_perf > 0.7:
                score += 20
            elif test_perf > 0.6:
                score += 10
        else:
            test_perf = metrics.get('test_r2', 0)
            if test_perf > 0.9:
                score += 40
            elif test_perf > 0.8:
                score += 30
            elif test_perf > 0.7:
                score += 20
            elif test_perf > 0.5:
                score += 10
        
        # Overfitting component (30%)
        overfitting_gap = metrics.get('overfitting_gap', 0)
        if overfitting_gap < 0.02:
            score += 30
        elif overfitting_gap < 0.05:
            score += 25
        elif overfitting_gap < 0.10:
            score += 15
        elif overfitting_gap < 0.15:
            score += 5
        
        # Stability component (30%)
        cv_std = metrics.get('cv_std', 0)
        if cv_std < 0.01:
            score += 30
        elif cv_std < 0.02:
            score += 25
        elif cv_std < 0.05:
            score += 15
        elif cv_std < 0.10:
            score += 5
        
        return min(score, 100)  # Cap at 100
    
