    def download_kaggle_readiness_report(self, successful_models):
        """Download Platform readiness assessment report"""
        report_data = []
        
        for model_name, metrics in successful_models.items():
            readiness_score = self.calculate_kaggle_readiness(metrics)
            overfitting_gap = metrics.get('overfitting_gap', 0)
            cv_std = metrics.get('cv_std', 0)
            
            # Recommendations
            recommendations = []
            if overfitting_gap > 0.1:
                recommendations.append("High overfitting - add regularization")
            if cv_std > 0.05:
                recommendations.append("Unstable CV - use ensemble methods")
            if readiness_score < 50:
                recommendations.append("Poor generalization - simplify model")
            if not recommendations:
                recommendations.append("Model ready for Platform submission")
            
            report_data.append({
                'Model': model_name,
                'Kaggle_Readiness_Score': readiness_score,
                'Overfitting_Gap': overfitting_gap,
                'CV_Stability': cv_std,
                'Recommendations': '; '.join(recommendations)
            })
        
        report_df = pd.DataFrame(report_data)
        csv = report_df.to_csv(index=False)
        
        from datetime import datetime
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        st.download_button(
            label="📥 Download Platform Readiness Report",
            data=csv,
            file_name=f"kaggle_readiness_{timestamp}.csv",
            mime="text/csv",
            key=f"kaggle_readiness_{int(__import__('time').time() * 1000)}"
        )
    
    def download_feature_importance_report(self, successful_models):
        """Download feature importance analysis"""
        st.info("Feature importance analysis for tree-based models")
        
        importance_data = []
        for model_name, metrics in successful_models.items():
            model = metrics.get('model')
            if hasattr(model, 'feature_importances_'):
                feature_names = st.session_state.get('feature_columns', [])
                importances = model.feature_importances_
                
                for feature, importance in zip(feature_names, importances):
                    importance_data.append({
                        'Model': model_name,
                        'Feature': feature,
                        'Importance': importance
                    })
        
        if importance_data:
            importance_df = pd.DataFrame(importance_data)
            
            # 🚨 KILL LIST AUDIT: Flag features with >40% importance
            st.markdown("### 🎯 Feature Importance Kill List Audit")
            for model_name in importance_df['Model'].unique():
                model_imp = importance_df[importance_df['Model'] == model_name].copy()
                total_imp = model_imp['Importance'].sum()
                if total_imp > 0:
                    model_imp['Importance_Pct'] = model_imp['Importance'] / total_imp * 100
                    model_imp = model_imp.sort_values('Importance_Pct', ascending=False)
                    
                    # Check for >40% importance (kill list)
                    kill_list = model_imp[model_imp['Importance_Pct'] > 40]
                    if len(kill_list) > 0:
                        st.error(f"🚨 **{model_name} - KILL LIST (>40% importance)**")
                        for _, row in kill_list.iterrows():
                            feat = row['Feature']
                            pct = row['Importance_Pct']
                            if str(feat).startswith('P') or str(feat).startswith('M'):
                                st.warning(f"  ⚠️ `{feat}`: {pct:.1f}% - **LIKELY LEAK** (P*/M* feature)")
                            else:
                                st.warning(f"  ⚠️ `{feat}`: {pct:.1f}% - **SUSPICIOUS**")
                        st.info("**Action**: Drop this feature and re-run. If R² crashes to ~0.005, it was your leak.")
                    else:
                        st.success(f"✅ {model_name}: No feature >40% importance")
                    
                    # Show top 5 features
                    with st.expander(f"Top 5 Features - {model_name}"):
                        for i, (_, row) in enumerate(model_imp.head(5).iterrows()):
                            st.write(f"  {i+1}. `{row['Feature']}`: {row['Importance_Pct']:.1f}%")
            
            csv = importance_df.to_csv(index=False)
            
            from datetime import datetime
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            st.download_button(
                label="📥 Download Feature Importance",
                data=csv,
                file_name=f"feature_importance_{timestamp}.csv",
                mime="text/csv",
                key=f"feature_importance_{int(__import__('time').time() * 1000)}"
            )
        else:
            st.warning("No feature importance data available (only for tree-based models)")
    
