    def download_overfitting_analysis_report(self, successful_models):
        """Download overfitting analysis report"""
        analysis_data = []
        
        for model_name, metrics in successful_models.items():
            if st.session_state.get('problem_type', 'regression') == 'classification':
                train_perf = metrics.get('train_accuracy', 0)
                test_perf = metrics.get('test_accuracy', 0)
            else:
                train_perf = metrics.get('train_r2', 0)
                test_perf = metrics.get('test_r2', 0)
            
            overfitting_gap = metrics.get('overfitting_gap', 0)
            
            # Analysis
            if overfitting_gap < 0.02:
                analysis = "Excellent generalization"
            elif overfitting_gap < 0.05:
                analysis = "Good generalization"
            elif overfitting_gap < 0.10:
                analysis = "Moderate overfitting"
            else:
                analysis = "High overfitting risk"
            
            analysis_data.append({
                'Model': model_name,
                'Train_Performance': train_perf,
                'Test_Performance': test_perf,
                'Overfitting_Gap': overfitting_gap,
                'Analysis': analysis
            })
        
        analysis_df = pd.DataFrame(analysis_data)
