    def generate_predictions(self, model_name, test_df):
        """Generate predictions using selected model"""
        try:
            # Get the trained model
            model_result = st.session_state.trained_models_enhanced[model_name]
            model = model_result['model']
            
            # Prepare test data (same preprocessing as training)
            X_test = test_df.copy()
            
            # Apply same preprocessing
            if st.session_state.get('label_encoders'):
                for col, encoder in st.session_state.label_encoders.items():
                    if col in X_test.columns:
                        # Handle unseen categories
                        X_test[col] = X_test[col].astype(str)
                        # Transform only known categories, use most frequent for unknown
                        known_categories = set(encoder.classes_)
                        X_test[col] = X_test[col].apply(
                            lambda x: x if x in known_categories else encoder.classes_[0]
                        )
                        X_test[col] = encoder.transform(X_test[col])
            
            # Scale features
            if st.session_state.get('feature_scaler'):
                # Select only the feature columns used in training that exist in test data
                feature_cols = st.session_state.get('feature_columns', [])
                if feature_cols:
                    # Only keep features that exist in both training and test data
                    available_features = [col for col in feature_cols if col in X_test.columns]
                    if len(available_features) < len(feature_cols):
                        missing_features = set(feature_cols) - set(available_features)
                        st.info(f"🔄 Some training features missing in test data: {len(missing_features)} features skipped")
                    
                    X_test_features = X_test[available_features] if available_features else X_test
                else:
                    X_test_features = X_test
                X_test_scaled = st.session_state.feature_scaler.transform(X_test_features)
            else:
                X_test_scaled = X_test
            
            # BULLETPROOF: Final feature alignment check
            expected_features = getattr(model, 'feature_names_in_', None)
            if expected_features is not None:
                # Ensure exact feature match
                available_features = list(X_test_scaled.columns) if hasattr(X_test_scaled, 'columns') else None
                if available_features:
                    missing_features = set(expected_features) - set(available_features)
                    extra_features = set(available_features) - set(expected_features)
                    
                    if missing_features or extra_features:
                        st.error(f"🚨 **FEATURE MISMATCH DETECTED**")
                        st.error(f"Missing: {len(missing_features)} features")
                        st.error(f"Extra: {len(extra_features)} features") 
                        st.error("**Solution**: Regenerate enhanced datasets using Step 3 Data Enhancement")
                        return None
            
            # Make predictions - WEBSOCKET TIMEOUT FIX
            with st.spinner(f"🔮 Generating predictions using {model_name}..."):
                predictions = model.predict(X_test_scaled)
            
            # Get probability scores if available and classification problem
            probability_scores = None
            if st.session_state.get('problem_type') == 'classification' and hasattr(model, 'predict_proba'):
                try:
                    with st.spinner("📊 Calculating prediction probabilities..."):
                        probability_scores = model.predict_proba(X_test_scaled)
                except:
                    probability_scores = None
            
            # Create submission dataframe
            if 'id' in test_df.columns:
                submission_df = pd.DataFrame({
                    'id': test_df['id'],
                    'prediction': predictions
                })
            else:
                submission_df = pd.DataFrame({
                    'prediction': predictions
                })
            
            # Display results
            st.success(f"Generated {len(predictions)} predictions using {model_name}")
            st.dataframe(submission_df.head())
            
            # Enhanced download options for predictions
            st.markdown("### 📥 Download Predictions")
            
            col1, col2, col3 = st.columns(3)
            
            with col1:
                # CSV Download with unique key
                csv_data = submission_df.to_csv(index=False)
                from datetime import datetime
                import time
                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                unique_id = int(time.time() * 1000)  # Add milliseconds for uniqueness
                
                st.download_button(
                    label="📊 Download CSV",
                    data=csv_data,
                    file_name=f"predictions_{model_name}_{timestamp}.csv",
                    mime="text/csv",
                    key=f"pred_csv_{model_name}_{unique_id}",
                    help="Download predictions in CSV format",
                    use_container_width=True
                )
            
            with col2:
                # JSON Download
                import json
                json_data = json.dumps({
                    'model': model_name,
                    'timestamp': timestamp,
                    'predictions': submission_df.to_dict('records'),
                    'metadata': {
                        'problem_type': st.session_state.get('problem_type', 'Unknown'),
                        'total_predictions': len(submission_df)
                    }
                }, indent=2)
                
                st.download_button(
                    label="📄 Download JSON",
                    data=json_data,
                    file_name=f"predictions_{model_name}_{timestamp}.json",
                    mime="application/json",
                    key=f"pred_json_{model_name}_{unique_id}",
                    help="Download predictions with metadata",
                    use_container_width=True
                )
            
            with col3:
                # Platform submission format
                kaggle_df = submission_df.copy()
                if 'id' in kaggle_df.columns:
                    kaggle_df.columns = ['id', 'target']
                else:
                    kaggle_df['id'] = range(len(kaggle_df))
                    kaggle_df = kaggle_df[['id', 'prediction']]
                    kaggle_df.columns = ['id', 'target']
                
                kaggle_csv = kaggle_df.to_csv(index=False)
                
                st.download_button(
                    label="🏆 Platform Format",
                    data=kaggle_csv,
                    file_name=f"submission_{model_name}_{timestamp}.csv",
                    mime="text/csv",
                    key=f"kaggle_csv_{model_name}_{unique_id}",
                    help="Download in standard Platform submission format",
                    use_container_width=True
                )
            
        except Exception as e:
            st.error(f"Failed to generate predictions: {str(e)}")
            st.error("Make sure the test data has the same structure as training data")
    
