    def get_algorithm_recommendations(self, dataset_size, num_features, problem_type):
        """Provide intelligent algorithm recommendations using SAME system as Dataset Overview"""
        
        # FIXED: Use identical system and normalization as Dataset Overview/Competition Analysis  
        rec_sys = UnifiedRecommendationSystem()
        
        # Normalize problem type using the same method as Dataset Overview
        normalized_problem_type = self._normalize_problem_type(problem_type)
        
        # Create a proper mock dataset that accurately reflects real dataset size
        # pandas already imported globally
        import numpy as np
        mock_dataset = pd.DataFrame(np.random.randn(dataset_size, num_features))
        
        # Use enhanced system with size awareness (SAME as Dataset Overview)
        enhanced_recommendations = rec_sys.recommend(normalized_problem_type, dataset=mock_dataset)
        
        # Get size category for reasoning
        size_category = rec_sys.dataset_size_category(mock_dataset)
        
        # Create reasoning based on dataset characteristics
        if size_category == "small":
            reasoning = f"Small dataset ({dataset_size:,} rows): Simple interpretable algorithms prevent overfitting"
        elif size_category == "medium":
            reasoning = f"Medium dataset ({dataset_size:,} rows): Balanced approach with ensemble methods"
        else:
            reasoning = f"Large dataset ({dataset_size:,} rows): Complex algorithms and GPU acceleration recommended"
        
        # Use enhanced recommendations (now consistent with Dataset Overview)
        recommended_algos = enhanced_recommendations['recommended']
        
        return {
            'top_algorithms': recommended_algos[:3],
            'reasoning': reasoning,
            'accuracy_focused': recommended_algos[:3],
            'speed_focused': recommended_algos[:3], 
            'robust_focused': recommended_algos[:3],
            'all_available': recommended_algos
        }
    
