                if comparison_data:
                    comparison_df = pd.DataFrame(comparison_data)
                    zip_file.writestr(f"model_comparison_{timestamp}.csv", comparison_df.to_csv(index=False))
                
                # 2. Platform readiness report
                readiness_data = []
                for model_name, metrics in successful_models.items():
                    readiness_data.append({
                        'Model': model_name,
                        'Kaggle_Readiness_Score': self.calculate_kaggle_readiness(metrics),
                        'Overfitting_Gap': metrics.get('overfitting_gap', 0),
                        'CV_Stability': metrics.get('cv_std', 0),
                        'Recommendation': 'Ready for submission' if self.calculate_kaggle_readiness(metrics) > 70 else 'Needs improvement'
                    })
                
                readiness_df = pd.DataFrame(readiness_data)
