    def capture_workflow_config(self, successful_models=None):
        """
        Safely capture workflow configuration and model results 
        without crashing on missing session state or None values.
        """

        # ✅ Core config with safe defaults
        config = {
            # Competition info
            "competition_name": getattr(st.session_state, 'competition_name', 'Unknown Competition'),
            "problem_type": getattr(st.session_state, 'problem_type', 'classification'),
            "target_column": getattr(st.session_state, 'target_column', 'target'),

            # Dataset info
            "dataset_info": {
                "train_file": getattr(st.session_state, 'train_file_path', None) or 'train.csv',
                "test_file": getattr(st.session_state, 'test_file_path', None) or 'test.csv',
                "feature_columns": getattr(st.session_state, 'feature_columns', None) or [],
            },

            # Preprocessing config
            "preprocessing": getattr(st.session_state, 'preprocess_config', None) or {},

            # Hyperparameters
            "hyperparameters": getattr(st.session_state, 'manual_hyperparams', {}),

            # Training config
            "training_config": {
                "test_size": getattr(st.session_state, 'test_size', 0.2),
                "random_state": getattr(st.session_state, 'random_state', 42),
                "cv_folds": getattr(st.session_state, 'cv_folds', 5),
            },

            # Model tracking placeholders
            "models": {},
            "best_score": 0,
            "best_model": None
        }

        # ✅ Safe iteration over successful_models
        if successful_models:
            for model_name, metrics in successful_models.items():
                config["models"][model_name] = {
                    "score": metrics.get('test_score', 0),
                    "cv_mean": metrics.get('cv_mean', 0),
                    "cv_std": metrics.get('cv_std', 0),
                    "params": metrics.get('params', {})
                }

                # Track best model
                if metrics.get('test_score', 0) > config["best_score"]:
                    config["best_score"] = metrics.get('test_score', 0)
                    config["best_model"] = model_name
        else:
            # Ensure consistent structure if no models ran
            config["models"] = {}
            config["best_score"] = 0
            config["best_model"] = None

        return config
    
