    def generate_model_training_code(self, config):
        """Generate model-specific training code"""
        best_model = config['best_model']
        
        if 'Random Forest' in best_model:
            if config['problem_type'] == 'classification':
                return [
                    "# Train Random Forest Classifier\n",
                    "from sklearn.ensemble import RandomForestClassifier\n",
                    "best_model = RandomForestClassifier(\n",
                    "    n_estimators=100,\n",
                    "    random_state=42\n",
                    ")\n",
                    "best_model.fit(X_train, y_train)\n",
                    "print('Random Forest Classifier trained successfully!')"
                ]
            else:
                return [
                    "# Train Random Forest Regressor\n",
                    "from sklearn.ensemble import RandomForestRegressor\n",
                    "best_model = RandomForestRegressor(\n",
                    "    n_estimators=100,\n",
                    "    random_state=42\n",
                    ")\n",
                    "best_model.fit(X_train, y_train)\n",
                    "print('Random Forest Regressor trained successfully!')"
                ]
                
        elif 'XGBoost' in best_model:
            return [
                "# Train XGBoost Model\n",
                "import xgboost as xgb\n",
                f"best_model = xgb.XGB{'Classifier' if config['problem_type'] == 'classification' else 'Regressor'}(\n",
                "    random_state=42\n",
                ")\n",
                "best_model.fit(X_train, y_train)\n",
                "print('XGBoost model trained successfully!')"
            ]
            
        else:  # Default to logistic regression/linear regression
            if config['problem_type'] == 'classification':
                return [
                    "# Train Logistic Regression\n",
                    "from sklearn.linear_model import LogisticRegression\n",
                    "best_model = LogisticRegression(max_iter=1000, random_state=42)\n",
                    "best_model.fit(X_train, y_train)\n",
                    "print('Logistic Regression trained successfully!')"
                ]
            else:
                return [
                    "# Train Linear Regression\n",
                    "from sklearn.linear_model import LinearRegression\n",
                    "best_model = LinearRegression()\n",
                    "best_model.fit(X_train, y_train)\n",
                    "print('Linear Regression trained successfully!')"
                ]
    
