                auto_time_features = st.checkbox("⏰ Time Series Features", help="Date decomposition, lag features, rolling statistics", key="standalone_time_features")
                auto_text_preprocessing = st.checkbox("📝 Text Preprocessing", help="NLP cleaning, vectorization, sentiment analysis", key="standalone_text_preprocessing")
                auto_dimensionality_reduction = st.checkbox("📉 Dimensionality Reduction", help="PCA, feature clustering, variance-based reduction", key="standalone_dimensionality_reduction")
                
                
                # Technical Indicators (NEW!)
