    def apply_technical_indicators(self, df, 
                                   include_macd=True,
                                   include_bollinger=True,
                                   include_rsi=True,
                                   include_vwap=False,
                                   include_stochastic=False,
                                   include_atr=False,
                                   lag_periods=None,
                                   target_column=None):
        """
        Apply technical indicators and lag features to the dataset.
        
        Args:
            df: Input DataFrame
            include_*: Flags for which indicators to include
            lag_periods: Custom lag periods (default [2, 5, 10, 20])
            target_column: Target column to EXCLUDE from feature generation (prevents leakage)
        
        Returns:
            DataFrame with added technical features
        """
        # Get target column from session state if not provided
        if target_column is None:
            target_column = (st.session_state.get('manual_target_column') or 
                           st.session_state.get('target_column', ''))
        
        try:
            from technical_indicators import AdvancedFeatureEngineer
            
            if lag_periods is None:
                lag_periods = [2, 5, 10, 20]
            
            engineer = AdvancedFeatureEngineer(
                lag_periods=lag_periods,
                include_macd=include_macd,
                include_bollinger=include_bollinger,
                include_rsi=include_rsi,
                include_vwap=include_vwap,
                include_stochastic=include_stochastic,
                include_atr=include_atr,
                target_column=target_column  # CRITICAL: Prevents leakage from target-derived features
            )
            
            numeric_cols = df.select_dtypes(include=[np.number]).columns.tolist()
            price_cols = [c for c in numeric_cols if any(x in c.lower() for x in ['price', 'close', 'return', 'value', 'excess'])]
            
            # CRITICAL: Exclude target column from price columns to prevent leakage
            if target_column:
                price_cols = [c for c in price_cols if c != target_column and target_column not in c]
            
            if not price_cols:
                price_cols = numeric_cols[:3]
            
            volume_col = next((c for c in numeric_cols if 'volume' in c.lower()), None)
            high_col = next((c for c in numeric_cols if 'high' in c.lower()), None)
            low_col = next((c for c in numeric_cols if 'low' in c.lower()), None)
            close_col = next((c for c in numeric_cols if 'close' in c.lower()), None)
            
            result = engineer.fit_transform(
                df,
                price_columns=price_cols[:5],
                volume_column=volume_col,
                high_column=high_col,
                low_column=low_col,
                close_column=close_col
            )
            
            return result
            
        except Exception as e:
            import traceback
            st.warning(f"Technical indicators error: {e}")
            return df
        """Permanent solution: Automatically detect and fix problematic enhanced datasets"""
        if 'datasets' not in st.session_state:
            return
            
        problematic_datasets = []
        fixed_datasets = {}
        
        for dataset_name, df in st.session_state.datasets.items():
            if dataset_name.startswith("enhanced_"):
                # Check for problematic feature patterns
                problematic_features = [col for col in df.columns if 
                    ('_x_' in col or '_div_' in col) and 
                    any(problem in col.lower() for problem in 
                        ['id', 'name', 'survived', 'target', 'sex', 'title', 'description'])]
                
                if problematic_features:
                    problematic_datasets.append((dataset_name, problematic_features))
                    
                    # Get the original dataset name
                    original_name = dataset_name.replace("enhanced_", "")
                    if original_name in st.session_state.datasets:
                        # Regenerate enhanced dataset with bulletproof method
                        original_df = st.session_state.datasets[original_name]
                        target_col = st.session_state.get('target_column', '')
                        
                        # Apply safe feature engineering
                        fixed_df = self.auto_feature_engineering_safe(original_df, target_col)
                        fixed_datasets[dataset_name] = fixed_df
        
        # Update problematic datasets
        if fixed_datasets:
            st.session_state.datasets.update(fixed_datasets)
            st.success(f"🔧 **PERMANENT FIX APPLIED**: Automatically regenerated {len(fixed_datasets)} problematic enhanced datasets")
            
            for dataset_name, bad_features in problematic_datasets:
                st.info(f"✅ Fixed {dataset_name}: Removed {len(bad_features)} problematic features")
                
        return len(fixed_datasets) > 0

    def auto_categorical_encoding(self, df):
        """Advanced categorical encoding with multiple strategies"""
        # pandas already imported globally
        from sklearn.preprocessing import LabelEncoder
        
        enhanced_df = df.copy()
        encoded_columns = []
        
        # Get categorical columns (exclude datetime and already processed text features)
        categorical_cols = enhanced_df.select_dtypes(include=['object', 'category']).columns
        categorical_cols = [col for col in categorical_cols if not any(suffix in col for suffix in ['_length', '_word_count', '_char_count'])]
        
        for col in categorical_cols:
            try:
                try:
                    unique_values = enhanced_df[col].nunique()
                except (TypeError, AttributeError):
                    # Skip if column contains unhashable types
                    continue
                null_pct = enhanced_df[col].isnull().sum() / len(enhanced_df)
                
                # Skip columns with too many nulls
                if null_pct > 0.5:
                    continue
                
                if unique_values <= 2:
                    # Binary encoding for 2 categories
                    le = LabelEncoder()
                    enhanced_df[col] = le.fit_transform(enhanced_df[col].astype(str).fillna('missing'))
                    encoded_columns.append(f"{col} (Binary)")
                elif unique_values <= 10:
                    # One-hot encoding for low cardinality
                    dummies = pd.get_dummies(enhanced_df[col], prefix=col, drop_first=True, dummy_na=True)
                    enhanced_df = pd.concat([enhanced_df.drop(col, axis=1), dummies], axis=1)
                    encoded_columns.append(f"{col} (One-Hot)")
                elif unique_values <= 50:
                    # Target encoding for medium cardinality (simulate with mean encoding)
                    le = LabelEncoder()
                    enhanced_df[col] = le.fit_transform(enhanced_df[col].astype(str).fillna('missing'))
                    encoded_columns.append(f"{col} (Label)")
                else:
                    # Hash encoding for very high cardinality
                    enhanced_df[col] = enhanced_df[col].astype(str).apply(lambda x: hash(x) % 1000)
                    encoded_columns.append(f"{col} (Hash)")
                    
            except Exception as e:
                # Fallback to simple label encoding
                le = LabelEncoder()
                enhanced_df[col] = le.fit_transform(enhanced_df[col].astype(str).fillna('missing'))
                encoded_columns.append(f"{col} (Fallback)")
        
        encoding_info = f"Smart-encoded {len(encoded_columns)} categorical columns"
        return enhanced_df, encoding_info

    def auto_class_balancing(self, df, balancing_method):
        """Apply class balancing techniques (SMOTE, undersampling, or auto-detect)"""
        # pandas already imported globally
        import numpy as np
        
        enhanced_df = df.copy()
        original_shape = enhanced_df.shape
        
        # Check if DataFrame is empty or has no columns
        if enhanced_df.empty or len(enhanced_df.columns) == 0:
            balancing_info = "Class balancing skipped - DataFrame is empty or has no columns"
            return enhanced_df, balancing_info
        
        # Try to detect target column
        target_col = (st.session_state.get('manual_target_column') or 
                     st.session_state.get('target_column', ''))
        
        if not target_col:
            # Auto-detect likely target column (last column or common names)
            common_targets = ['target', 'label', 'class', 'y', 'survived', 'outcome']
            target_candidates = [col for col in enhanced_df.columns if col.lower() in common_targets]
            if target_candidates:
                target_col = target_candidates[0]
            else:
                target_col = enhanced_df.columns[-1]  # Last column as fallback
        
        if target_col not in enhanced_df.columns:
            return enhanced_df, "Class balancing skipped - no valid target column found"
        
        try:
            # Check if target is categorical/classification
            target_series = enhanced_df[target_col]
            try:
                unique_values = target_series.nunique()
            except (TypeError, AttributeError):
                # If nunique() fails, skip class balancing
                return enhanced_df, "Class balancing skipped - unable to count unique values in target"
            
            # Only apply to classification problems (2-10 unique values)
            if unique_values < 2 or unique_values > 10:
                return enhanced_df, f"Class balancing skipped - target has {unique_values} unique values (not classification)"
            
            # Check class distribution
            class_counts = target_series.value_counts()
            imbalance_ratio = class_counts.max() / class_counts.min()
            
            if imbalance_ratio < 2:
                return enhanced_df, f"Class balancing skipped - classes already balanced (ratio: {imbalance_ratio:.2f})"
            
            # Separate features and target
            X = enhanced_df.drop(columns=[target_col])
            y = enhanced_df[target_col]
            
            # Apply balancing method
            if balancing_method == "SMOTE (Oversampling)":
                balanced_X, balanced_y, method_used = self._apply_smote_balancing(X, y)
            elif balancing_method == "Random Undersampling":
                balanced_X, balanced_y, method_used = self._apply_undersampling(X, y)
            else:  # Auto-Detect Best Method
                # For small datasets, use SMOTE; for large datasets, use undersampling
                if len(enhanced_df) < 5000:
                    balanced_X, balanced_y, method_used = self._apply_smote_balancing(X, y)
                else:
                    balanced_X, balanced_y, method_used = self._apply_undersampling(X, y)
            
            # Combine back into DataFrame
            enhanced_df = balanced_X.copy()
            enhanced_df[target_col] = balanced_y
            
            final_shape = enhanced_df.shape
            new_class_counts = enhanced_df[target_col].value_counts()
            balancing_info = f"{method_used}: {original_shape} → {final_shape}, class distribution: {dict(new_class_counts)}"
            
            return enhanced_df, balancing_info
            
        except Exception as e:
            return enhanced_df, f"Class balancing failed: {str(e)[:60]}"

    def auto_dimensionality_reduction(self, df):
        """Apply dimensionality reduction when appropriate"""
        # pandas already imported globally
        import numpy as np
        
        enhanced_df = df.copy()
        original_features = enhanced_df.shape[1]
        
        # Only apply if we have many features
        if original_features > 50:
            try:
                from sklearn.decomposition import PCA
                from sklearn.preprocessing import StandardScaler
                
                # CRITICAL: Protect target columns from PCA
                target_keywords = ['target', 'y', 'label', 'survived', 'outcome', 'class', 'forward', 'excess', 'returns', 'market']
                target_cols = [col for col in enhanced_df.columns if any(keyword in col.lower() for keyword in target_keywords)]
                
                # Get numeric columns EXCLUDING target columns
                all_numeric_cols = enhanced_df.select_dtypes(include=['number']).columns
                numeric_cols_for_pca = [col for col in all_numeric_cols if col not in target_cols]
                
                if len(numeric_cols_for_pca) > 10:
                    # Apply PCA only to non-target numeric columns
                    numeric_data = enhanced_df[numeric_cols_for_pca].fillna(0)
                    
                    # Scale first
                    scaler = StandardScaler()
                    scaled_data = scaler.fit_transform(numeric_data)
                    
                    # Apply PCA to retain 95% variance
                    pca = PCA(n_components=0.95)
                    pca_features = pca.fit_transform(scaled_data)
                    
                    # Create PCA components dataframe
                    pca_df = pd.DataFrame(pca_features, 
                                        columns=[f'PCA_{i+1}' for i in range(pca_features.shape[1])],
                                        index=enhanced_df.index)
                    
                    # Keep non-numeric columns, target columns, and add PCA components
                    non_numeric_df = enhanced_df.select_dtypes(exclude=['number'])
                    target_df = enhanced_df[target_cols] if target_cols else pd.DataFrame()
                    
                    if target_cols and not non_numeric_df.empty:
                        enhanced_df = pd.concat([non_numeric_df, target_df, pca_df], axis=1)
                    elif target_cols:
                        enhanced_df = pd.concat([target_df, pca_df], axis=1)
                    else:
                        enhanced_df = pd.concat([non_numeric_df, pca_df], axis=1)
                    
                    final_features = enhanced_df.shape[1]
                    dim_info = f"PCA applied: {original_features} → {final_features} features (95% variance retained, target columns preserved)"
                else:
                    dim_info = "Dimensionality reduction skipped - insufficient numeric features"
            except Exception as e:
                dim_info = f"Dimensionality reduction skipped - {str(e)[:50]}"
        else:
            dim_info = "Dimensionality reduction skipped - feature count below threshold"
        
        return enhanced_df, dim_info

    def auto_feature_engineering_safe(self, df, target_column=None):
        """Bulletproof feature engineering - only creates safe, meaningful interactions"""
        # pandas already imported globally
        import numpy as np
        
        df_enhanced = df.copy()
        
        # Get bulletproof list of safe columns
        safe_cols = self.get_safe_feature_columns(df_enhanced, target_column)
        
        if len(safe_cols) >= 2:
            # Limit to top 5 most suitable columns to avoid explosion of features
            top_cols = safe_cols[:5]
            
            interactions_created = 0
            max_interactions = 10  # Prevent feature explosion
            
            for i, col1 in enumerate(top_cols):
                if interactions_created >= max_interactions:
                    break
                    
                for j, col2 in enumerate(top_cols[i+1:], i+1):
                    if interactions_created >= max_interactions:
                        break
                        
                    try:
                        # Verify both columns are still numeric and safe
                        if (pd.api.types.is_numeric_dtype(df_enhanced[col1]) and 
                            pd.api.types.is_numeric_dtype(df_enhanced[col2])):
                            
                            # Create multiplication interaction
                            interaction_name = f"{col1}_x_{col2}"
                            df_enhanced[interaction_name] = df_enhanced[col1] * df_enhanced[col2]
                            interactions_created += 1
                            
                            # Create division interaction (with safe denominator)
                            if interactions_created < max_interactions:
                                division_name = f"{col1}_div_{col2}"
                                df_enhanced[division_name] = df_enhanced[col1] / (df_enhanced[col2] + 1e-8)
                                interactions_created += 1
                                
                    except Exception as e:
                        continue  # Skip any problematic combinations
        
        return df_enhanced

    def auto_feature_scaling(self, df):
        """Apply feature scaling and normalization"""
        from sklearn.preprocessing import StandardScaler, MinMaxScaler
        # pandas already imported globally
        
        enhanced_df = df.copy()
        numeric_cols = list(enhanced_df.select_dtypes(include=['number']).columns)
        
        # CRITICAL: Exclude target columns from scaling
        target_keywords = ['target', 'y', 'label', 'survived', 'outcome', 'class', 'forward', 'excess', 'returns', 'market']
        cols_to_scale = [col for col in numeric_cols if not any(keyword in col.lower() for keyword in target_keywords)]
        
        if len(cols_to_scale) > 0:
            # Use StandardScaler for normal-like distributions
            scaler = StandardScaler()
            enhanced_df[cols_to_scale] = scaler.fit_transform(enhanced_df[cols_to_scale])
        
        return enhanced_df

    def auto_feature_selection(self, df):
        """Automatically select relevant features"""
        # pandas already imported globally
        import numpy as np
        
        enhanced_df = df.copy()
        original_features = enhanced_df.shape[1]
        
        # CRITICAL: Protect target columns from removal
        target_keywords = ['target', 'y', 'label', 'survived', 'outcome', 'class', 'forward', 'excess', 'returns', 'market']
        protected_cols = [col for col in enhanced_df.columns if any(keyword in col.lower() for keyword in target_keywords)]
        
        # Remove highly correlated features (but NOT target columns)
        numeric_cols = enhanced_df.select_dtypes(include=['number']).columns
        
        if len(numeric_cols) > 1:
            corr_matrix = enhanced_df[numeric_cols].corr().abs()
            
            # Find pairs of highly correlated features (>0.95)
            high_corr_pairs = []
            for i in range(len(corr_matrix.columns)):
                for j in range(i+1, len(corr_matrix.columns)):
                    if corr_matrix.iloc[i, j] > 0.95:
                        high_corr_pairs.append((corr_matrix.columns[i], corr_matrix.columns[j]))
            
            # Remove one feature from each highly correlated pair (skip protected columns)
            features_to_remove = set()
            for pair in high_corr_pairs:
                # Remove second feature only if it's NOT a protected target column
                if pair[1] not in protected_cols:
                    features_to_remove.add(pair[1])
            
            enhanced_df = enhanced_df.drop(columns=list(features_to_remove))
        
        # Remove constant features (but NOT target columns)
        constant_features = []
        for col in enhanced_df.columns:
            # SKIP protected columns
            if col in protected_cols:
                continue
            try:
                if enhanced_df[col].nunique() <= 1:
                    constant_features.append(col)
            except (TypeError, AttributeError):
                # Skip if column contains unhashable types
                pass
        
        enhanced_df = enhanced_df.drop(columns=constant_features)
        
        final_features = enhanced_df.shape[1]
        removed_features = original_features - final_features
        
        selection_info = f"Removed {removed_features} redundant/constant features"
        return enhanced_df, selection_info

    def auto_model_selection(self):
        """Automatically select the best performing model"""
        try:
            trained_models = st.session_state.get('trained_models_enhanced', {})
            successful_models = {k: v for k, v in trained_models.items() if 'error' not in v and v is not None}
            
            if not successful_models:
                return None
            
            problem_type = st.session_state.get('problem_type', 'classification')
            
            # Create scoring based on multiple metrics
            scored_models = {}
            
            if problem_type == 'classification':
                for model_name, metrics in successful_models.items():
                    test_acc = metrics.get('test_accuracy', 0)
                    cv_mean = metrics.get('cv_mean', 0) 
                    cv_std = metrics.get('cv_std', 1)
                    overfitting_gap = metrics.get('overfitting_gap', 1)
                    
                    # Combined score: accuracy, stability, generalization
                    score = (test_acc * 0.4) + (cv_mean * 0.4) + ((1 - cv_std) * 0.1) + ((1 - overfitting_gap) * 0.1)
                    scored_models[model_name] = score
            else:
                for model_name, metrics in successful_models.items():
                    test_r2 = metrics.get('test_r2', 0)
                    cv_mean = metrics.get('cv_mean', 0)
                    cv_std = metrics.get('cv_std', 1) 
                    overfitting_gap = metrics.get('overfitting_gap', 1)
                    
                    # Combined score for regression
                    score = (test_r2 * 0.4) + (cv_mean * 0.4) + ((1 - cv_std) * 0.1) + ((1 - overfitting_gap) * 0.1)
                    scored_models[model_name] = score
            
            if scored_models:
                best_model = max(scored_models.items(), key=lambda x: x[1])
                st.session_state.best_selected_model = best_model[0]
                st.session_state.best_model_score = best_model[1]
                return best_model[0]
            
            return None
            
        except Exception as e:
            st.error(f"Model selection failed: {str(e)}")
            return None

    def auto_outlier_detection(self, df):
        """Automatically detect and handle outliers"""
        import numpy as np
        
        df_cleaned = df.copy()
        numeric_cols = df_cleaned.select_dtypes(include=["int64", "float64"]).columns
        
        for col in numeric_cols:
            Q1 = df_cleaned[col].quantile(0.25)
            Q3 = df_cleaned[col].quantile(0.75)
            IQR = Q3 - Q1
            
            # Define outlier bounds
            lower_bound = Q1 - 1.5 * IQR
            upper_bound = Q3 + 1.5 * IQR
            
            # Cap outliers instead of removing them
            df_cleaned[col] = np.clip(df_cleaned[col], lower_bound, upper_bound)
        
        return df_cleaned

