    def auto_text_preprocessing(self, df):
        """Preprocess text columns with basic NLP techniques"""
        # pandas already imported globally
        import re
        
        enhanced_df = df.copy()
        text_features_added = 0
        
        # Identify text columns (object columns with high average string length)
        text_cols = []
        for col in enhanced_df.select_dtypes(include=['object']).columns:
            if enhanced_df[col].notna().sum() > 0:
                avg_length = enhanced_df[col].dropna().astype(str).str.len().mean()
                if avg_length > 10:  # Average length > 10 characters suggests text
                    text_cols.append(col)
        
        for col in text_cols:
            # Basic text features
            enhanced_df[f'{col}_length'] = enhanced_df[col].astype(str).str.len()
            enhanced_df[f'{col}_word_count'] = enhanced_df[col].astype(str).str.split().str.len()
            enhanced_df[f'{col}_char_count'] = enhanced_df[col].astype(str).str.len()
            enhanced_df[f'{col}_uppercase_ratio'] = enhanced_df[col].astype(str).apply(lambda x: sum(1 for c in x if c.isupper()) / len(x) if len(x) > 0 else 0)
            enhanced_df[f'{col}_digit_count'] = enhanced_df[col].astype(str).str.count(r'\d')
            text_features_added += 5
        
        text_info = f"Extracted {text_features_added} text features from {len(text_cols)} text columns"
        return enhanced_df, text_info

    def auto_time_series_features(self, df):
        """Extract time-based features from datetime columns"""
        # pandas already imported globally
        
        enhanced_df = df.copy()
        time_features_added = 0
        
        # Detect datetime columns
        datetime_cols = enhanced_df.select_dtypes(include=['datetime', 'datetime64']).columns
        
        # Try to parse object columns as datetime
        for col in enhanced_df.select_dtypes(include=['object']).columns:
            try:
                # Try common datetime patterns
                enhanced_df[col] = pd.to_datetime(enhanced_df[col], errors='coerce')
                if enhanced_df[col].notna().sum() > len(enhanced_df) * 0.5:  # More than 50% valid dates
                    datetime_cols = datetime_cols.tolist() + [col]
            except:
                continue
        
        for col in datetime_cols:
            if enhanced_df[col].dtype in ['datetime64[ns]', 'datetime64']:
                # Extract time components
                enhanced_df[f'{col}_year'] = enhanced_df[col].dt.year
                enhanced_df[f'{col}_month'] = enhanced_df[col].dt.month
                enhanced_df[f'{col}_day'] = enhanced_df[col].dt.day
                enhanced_df[f'{col}_weekday'] = enhanced_df[col].dt.weekday
                enhanced_df[f'{col}_hour'] = enhanced_df[col].dt.hour
                enhanced_df[f'{col}_is_weekend'] = (enhanced_df[col].dt.weekday >= 5).astype(int)
                time_features_added += 6
        
        time_info = f"Extracted {time_features_added} time-based features from {len(datetime_cols)} datetime columns"
        return enhanced_df, time_info

