            ensemble_info = {
                'type': 'voting_ensemble',
                'models': list(successful_models.keys())[:5],  # Top 5 models
                'created_at': datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            }
            
            # Calculate ensemble metrics
