    # Automated technique implementation methods
    def auto_missing_value_imputation(self, df):
        """Automatically handle missing values"""
        from sklearn.impute import SimpleImputer
        
        df_imputed = df.copy()
        
        # Numerical columns - use median imputation
        numeric_cols = df_imputed.select_dtypes(include=["int64", "float64"]).columns
        if len(numeric_cols) > 0:
            imputer = SimpleImputer(strategy="median")
            df_imputed[numeric_cols] = imputer.fit_transform(df_imputed[numeric_cols])
        
        # Categorical columns - use mode imputation
        categorical_cols = df_imputed.select_dtypes(include=["object", "category"]).columns
        if len(categorical_cols) > 0:
            # Clean categorical columns: convert list values to strings (fix unhashable type error)
            def standardize_list(value):
                if isinstance(value, list):
                    # Convert ['a', 'b'] to 'a, b'
                    return ', '.join(map(str, value))
                return value
            
            for col in categorical_cols:
                df_imputed[col] = df_imputed[col].apply(standardize_list)
            
            imputer = SimpleImputer(strategy="most_frequent")
            df_imputed[categorical_cols] = imputer.fit_transform(df_imputed[categorical_cols])
        
        return df_imputed
    
    def auto_outlier_detection(self, df):
        """Automatically detect and handle outliers"""
        import numpy as np
        
        df_cleaned = df.copy()
        numeric_cols = df_cleaned.select_dtypes(include=["int64", "float64"]).columns
        
        for col in numeric_cols:
            Q1 = df_cleaned[col].quantile(0.25)
            Q3 = df_cleaned[col].quantile(0.75)
            IQR = Q3 - Q1
            
            # Define outlier bounds
            lower_bound = Q1 - 1.5 * IQR
            upper_bound = Q3 + 1.5 * IQR
            
            # Cap outliers instead of removing them
            df_cleaned[col] = np.clip(df_cleaned[col], lower_bound, upper_bound)
        
        return df_cleaned
    
    def get_safe_feature_columns(self, df, target_column=None):
        """Bulletproof method to get safe columns for feature engineering"""
        # pandas already imported globally
        import numpy as np
        
        # Start with all columns
        all_cols = df.columns.tolist()
        safe_cols = []
        
        for col in all_cols:
            # Skip if column name indicates it's unsafe
            col_lower = str(col).lower()
            
            # EXCLUDE: Target column candidates
            target_keywords = ['target', 'y', 'label', 'survived', 'outcome', 'class', 'prediction']
            if target_column and str(target_column).lower() == col_lower:
                continue
            if any(keyword in col_lower for keyword in target_keywords):
                continue
                
            # EXCLUDE: ID columns
            id_keywords = ['id', '_id', 'index', 'key']
            if any(keyword in col_lower for keyword in id_keywords):
                continue
                
            # EXCLUDE: Text/categorical columns that shouldn't be in interactions
            text_keywords = ['name', 'title', 'description', 'text', 'comment']
            if any(keyword in col_lower for keyword in text_keywords):
                continue
                
            # EXCLUDE: Non-numeric or invalid columns for math operations
            try:
                # Must be numeric and have reasonable variance
                if pd.api.types.is_numeric_dtype(df[col]):
                    try:
                        if df[col].nunique() > 1 and not df[col].isnull().all():
                            # Additional check: must be suitable for mathematical operations
                            test_vals = df[col].dropna().head(100)
                            if len(test_vals) > 0 and np.isfinite(test_vals).all():
                                safe_cols.append(col)
                    except (TypeError, AttributeError):
                        # Skip if column contains unhashable types like lists
                        continue
            except:
                continue
                
        return safe_cols
    
    def auto_feature_engineering_safe(self, df, target_column=None):
        """Bulletproof feature engineering - only creates safe, meaningful interactions"""
        # pandas already imported globally
        import numpy as np
        
        df_enhanced = df.copy()
        
        # Get bulletproof list of safe columns
        safe_cols = self.get_safe_feature_columns(df_enhanced, target_column)
        
        if len(safe_cols) >= 2:
            # Limit to top 5 most suitable columns to avoid explosion of features
            top_cols = safe_cols[:5]
            
            interactions_created = 0
            max_interactions = 10  # Prevent feature explosion
            
            for i, col1 in enumerate(top_cols):
                if interactions_created >= max_interactions:
                    break
                    
                for j, col2 in enumerate(top_cols[i+1:], i+1):
                    if interactions_created >= max_interactions:
                        break
                        
                    try:
                        # Verify both columns are still numeric and safe
                        if (pd.api.types.is_numeric_dtype(df_enhanced[col1]) and 
                            pd.api.types.is_numeric_dtype(df_enhanced[col2])):
                            
                            # Create multiplication interaction
                            interaction_name = f"{col1}_x_{col2}"
                            df_enhanced[interaction_name] = df_enhanced[col1] * df_enhanced[col2]
                            interactions_created += 1
                            
                            # Create division interaction (with safe denominator)
                            if interactions_created < max_interactions:
                                division_name = f"{col1}_div_{col2}"
                                df_enhanced[division_name] = df_enhanced[col1] / (df_enhanced[col2] + 1e-8)
                                interactions_created += 1
                                
                    except Exception as e:
                        continue  # Skip any problematic combinations
        
        return df_enhanced

    def auto_feature_engineering(self, df):
        """Automatically create new features (Kaggle-ready - bulletproof version)"""
        # CRITICAL FIX: Use proper target column with fallback
        target_col = (st.session_state.get('manual_target_column') or 
                     st.session_state.get('target_column', ''))
        return self.auto_feature_engineering_safe(df, target_col)
    
    def validate_and_fix_datasets(self):
        """Permanent solution: Automatically detect and fix problematic enhanced datasets"""
        if 'datasets' not in st.session_state:
            return
            
        problematic_datasets = []
        fixed_datasets = {}
        
        for dataset_name, df in st.session_state.datasets.items():
            if dataset_name.startswith("enhanced_"):
                # Check for problematic feature patterns
                problematic_features = [col for col in df.columns if 
                    ('_x_' in col or '_div_' in col) and 
                    any(problem in col.lower() for problem in 
                        ['id', 'name', 'survived', 'target', 'sex', 'title', 'description'])]
                
                if problematic_features:
                    problematic_datasets.append((dataset_name, problematic_features))
                    
                    # Get the original dataset name
                    original_name = dataset_name.replace("enhanced_", "")
                    if original_name in st.session_state.datasets:
                        # Regenerate enhanced dataset with bulletproof method
                        original_df = st.session_state.datasets[original_name]
                        target_col = st.session_state.get('target_column', '')
                        
                        # Apply safe feature engineering
                        fixed_df = self.auto_feature_engineering_safe(original_df, target_col)
                        fixed_datasets[dataset_name] = fixed_df
        
        # Update problematic datasets
        if fixed_datasets:
            st.session_state.datasets.update(fixed_datasets)
            st.success(f"🔧 **PERMANENT FIX APPLIED**: Automatically regenerated {len(fixed_datasets)} problematic enhanced datasets")
            
            for dataset_name, bad_features in problematic_datasets:
                st.info(f"✅ Fixed {dataset_name}: Removed {len(bad_features)} problematic features")
                
        return len(fixed_datasets) > 0
    
    def auto_data_quality_check(self, df):
        """Automatically check data quality"""
        quality_report = {
            "missing_percentage": f"{(df.isnull().sum().sum() / df.size) * 100:.2f}%",
            "duplicate_rows": df.duplicated().sum(),
            "memory_usage_mb": f"{df.memory_usage(deep=True).sum() / 1024**2:.1f} MB"
        }
        return quality_report
    
    def auto_distribution_analysis(self, df):
        """Automatically analyze feature distributions"""
        try:
            from scipy import stats
            
            distribution_analysis = {}
            numeric_cols = df.select_dtypes(include=["int64", "float64"]).columns
            
            for col in numeric_cols[:5]:  # Analyze top 5 columns
                skewness = stats.skew(df[col].dropna())
                distribution_analysis[f"{col}_skewness"] = f"{skewness:.3f}"
                
                if abs(skewness) > 1:
                    distribution_analysis[f"{col}_recommendation"] = "Transformation recommended"
            
            return distribution_analysis
        except ImportError:
            return {"note": "Scipy not available for distribution analysis"}
    
    def auto_correlation_analysis(self, df):
        """Automatically analyze feature correlations"""
        correlation_analysis = {}
        numeric_cols = df.select_dtypes(include=["int64", "float64"]).columns
        
        if len(numeric_cols) > 1:
            corr_matrix = df[numeric_cols].corr()
            high_corr_pairs = []
            
            for i in range(len(corr_matrix.columns)):
                for j in range(i+1, len(corr_matrix.columns)):
                    corr_value = abs(corr_matrix.iloc[i, j])
                    if corr_value > 0.8:
                        high_corr_pairs.append(f"{corr_matrix.columns[i]} - {corr_matrix.columns[j]}: {corr_value:.3f}")
            
            correlation_analysis["high_correlation_pairs"] = high_corr_pairs if high_corr_pairs else ["No high correlations found"]
        
        return correlation_analysis
    
