    def apply_technical_indicators(self, df, 
                                   include_macd=True,
                                   include_bollinger=True,
                                   include_rsi=True,
                                   include_vwap=False,
                                   include_stochastic=False,
                                   include_atr=False,
                                   lag_periods=None,
                                   target_column=None):
        """
        Apply technical indicators and lag features to the dataset.
        
        Args:
            df: Input DataFrame
            include_*: Flags for which indicators to include
            lag_periods: Custom lag periods (default [2, 5, 10, 20])
            target_column: Target column to EXCLUDE from feature generation (prevents leakage)
        
        Returns:
            DataFrame with added technical features
        """
        # Get target column from session state if not provided
        if target_column is None:
            target_column = (st.session_state.get('manual_target_column') or 
                           st.session_state.get('target_column', ''))
        
        try:
            from technical_indicators import AdvancedFeatureEngineer
            
            if lag_periods is None:
                lag_periods = [2, 5, 10, 20]
            
            engineer = AdvancedFeatureEngineer(
                lag_periods=lag_periods,
                include_macd=include_macd,
                include_bollinger=include_bollinger,
                include_rsi=include_rsi,
                include_vwap=include_vwap,
                include_stochastic=include_stochastic,
                include_atr=include_atr,
                target_column=target_column  # CRITICAL: Prevents leakage from target-derived features
            )
            
            numeric_cols = df.select_dtypes(include=[np.number]).columns.tolist()
            price_cols = [c for c in numeric_cols if any(x in c.lower() for x in ['price', 'close', 'return', 'value', 'excess'])]
            
            # CRITICAL: Exclude target column from price columns to prevent leakage
            if target_column:
                price_cols = [c for c in price_cols if c != target_column and target_column not in c]
            
            if not price_cols:
                price_cols = numeric_cols[:3]
            
            volume_col = next((c for c in numeric_cols if 'volume' in c.lower()), None)
            high_col = next((c for c in numeric_cols if 'high' in c.lower()), None)
            low_col = next((c for c in numeric_cols if 'low' in c.lower()), None)
            close_col = next((c for c in numeric_cols if 'close' in c.lower()), None)
            
            result = engineer.fit_transform(
                df,
                price_columns=price_cols[:5],
                volume_column=volume_col,
                high_column=high_col,
                low_column=low_col,
                close_column=close_col
            )
            
            return result
            
        except Exception as e:
            import traceback
            st.warning(f"Technical indicators error: {e}")
            return df
        """Permanent solution: Automatically detect and fix problematic enhanced datasets"""
        if 'datasets' not in st.session_state:
            return
            
        problematic_datasets = []
        fixed_datasets = {}
        
        for dataset_name, df in st.session_state.datasets.items():
            if dataset_name.startswith("enhanced_"):
                # Check for problematic feature patterns
                problematic_features = [col for col in df.columns if 
                    ('_x_' in col or '_div_' in col) and 
                    any(problem in col.lower() for problem in 
                        ['id', 'name', 'survived', 'target', 'sex', 'title', 'description'])]
                
                if problematic_features:
                    problematic_datasets.append((dataset_name, problematic_features))
                    
                    # Get the original dataset name
                    original_name = dataset_name.replace("enhanced_", "")
                    if original_name in st.session_state.datasets:
                        # Regenerate enhanced dataset with bulletproof method
                        original_df = st.session_state.datasets[original_name]
                        target_col = st.session_state.get('target_column', '')
                        
                        # Apply safe feature engineering
                        fixed_df = self.auto_feature_engineering_safe(original_df, target_col)
                        fixed_datasets[dataset_name] = fixed_df
        
        # Update problematic datasets
        if fixed_datasets:
            st.session_state.datasets.update(fixed_datasets)
            st.success(f"🔧 **PERMANENT FIX APPLIED**: Automatically regenerated {len(fixed_datasets)} problematic enhanced datasets")
            
            for dataset_name, bad_features in problematic_datasets:
                st.info(f"✅ Fixed {dataset_name}: Removed {len(bad_features)} problematic features")
                
        return len(fixed_datasets) > 0
    
