    def fix_data_leakage(self, train_df, test_df, target_column, leaky_columns=None):
        """✅ FIX: Properly preprocess data WITHOUT leakage"""
        from sklearn.preprocessing import StandardScaler
        # pandas already imported globally
        import numpy as np
        
        try:
            # Default leaky columns to drop if not specified
            if leaky_columns is None:
                leaky_columns = []
            
            # Separate features and target
            columns_to_drop = [target_column] + [col for col in leaky_columns if col in train_df.columns]
            X_train = train_df.drop(columns=columns_to_drop, errors='ignore')
            y_train = train_df[target_column]
            X_test = test_df.drop(columns=columns_to_drop, errors='ignore')
            y_test = test_df[target_column] if target_column in test_df.columns else None
            
            # ✅ CRITICAL: Align columns between train and test
            common_cols = list(set(X_train.columns) & set(X_test.columns))
            common_cols = sorted(common_cols)
            
            if not common_cols:
                return None, None, f"❌ No common columns between train and test!"
            
            X_train = X_train[common_cols]
            X_test = X_test[common_cols]
            
            # Identify numeric columns for scaling only
            numeric_cols = X_train.select_dtypes(include=[np.number]).columns.tolist()
            
            if numeric_cols:
                # ✅ FIX: Fit scaler ONLY on training data
                scaler = StandardScaler()
                X_train_scaled = scaler.fit_transform(X_train[numeric_cols])
                X_test_scaled = scaler.transform(X_test[numeric_cols])
                
                X_train_scaled_df = pd.DataFrame(X_train_scaled, columns=numeric_cols, index=X_train.index)
                X_test_scaled_df = pd.DataFrame(X_test_scaled, columns=numeric_cols, index=X_test.index)
                
                X_train_fixed = pd.concat([X_train_scaled_df, X_train.drop(columns=numeric_cols)], axis=1)
                X_test_fixed = pd.concat([X_test_scaled_df, X_test.drop(columns=numeric_cols)], axis=1)
            else:
                X_train_fixed = X_train.copy()
                X_test_fixed = X_test.copy()
            
            # Add target back
            train_fixed = X_train_fixed.copy()
            train_fixed[target_column] = y_train.values
            
            test_fixed = X_test_fixed.copy()
            if y_test is not None:
                test_fixed[target_column] = y_test.values
            
            dropped_msg = f" (dropped: {', '.join(leaky_columns)})" if leaky_columns else ""
            return train_fixed, test_fixed, f"✅ Data leakage FIXED! (aligned & scaled{dropped_msg})"
        except Exception as e:
            return None, None, f"❌ Error: {str(e)}"
    
