    def render_enhanced_competition_analysis(self):
        """Manual competition analysis with advanced domain detection"""
        
        # -------------------------------
        # SESSION-CACHED UNIFIED ALGORITHMS
        # -------------------------------
        ALGORITHMS_REGISTRY = {}
        ALGORITHM_DISPLAY_NAMES = {}

        # Example: flags for availability
        XGB_AVAILABLE = True
        LGB_AVAILABLE = True

        # FIXED: Remove deprecated wrapper - use UnifiedRecommendationSystem directly

        # -------------------------------
        # ADVANCED TARGET COLUMN DETECTION
        # -------------------------------
        def detect_target_column(dataset_df: pd.DataFrame, problem_type: str, text_to_analyze: str = "") -> Dict[str, Any]:
            target_scores = {}
            target_patterns = {
                'classification': ['target', 'label', 'class', 'outcome', 'result', 'success', 'failure'],
                'regression': ['price', 'score', 'amount', 'value', 'metric'],
                'time_series': ['forecast', 'target', 'y', 'demand']
            }
            
            for col in dataset_df.columns:
                score = 0
                matched = []
                col_lower = col.lower()
                for pattern in target_patterns.get(problem_type, []):
                    if pattern in col_lower:
                        score += 5
                        matched.append(pattern)
                if re.search(r'target\s+column\s+is\s+`?' + re.escape(col_lower) + r'`?', text_to_analyze):
                    score += 10
                    matched.append("description_match")
                if score > 0:
                    target_scores[col] = {'score': score, 'matches': matched}
            return target_scores

        # -------------------------------
        # ADVANCED NLP PROCESSOR
        # -------------------------------
        class AdvancedNLPProcessor:
            def __init__(self):
                self.domain_keywords = {
                    'image_cv': ['image','photo','pixel','visual','cv','vision','segmentation','object','classification'],
                    'nlp_text': ['text','language','nlp','tokenization','embedding','sentiment','classification','translation'],
                    'time_series': ['time','temporal','series','forecast','trend','seasonal','daily','monthly','hourly'],
                    'tabular_structured': ['feature','column','dataset','categorical','numeric','label','target']
                }
                self.strategy_templates = {
                    'image_cv': [
                        "Fine-tune EfficientNet/ResNet with AutoAugment/MixUp/CutMix",
                        "Consider Vision Transformers (ViT/Swin) with ensembling",
                        "Use test-time augmentation for robustness"
                    ],
                    'nlp_text': [
                        "Fine-tune BERT/RoBERTa/DeBERTa with LR schedules and warmup",
                        "Combine embeddings with LightGBM for tabular+text tasks",
                        "Use data augmentation (back translation, synonym replacement)"
                    ],
                    'time_series': [
                        "Gradient boosting baselines with lag/rolling features",
                        "LSTM or Transformer-based models for sequence patterns",
                        "Time-series-specific validation (TimeSeriesSplit/PurgedKFold)"
                    ],
                    'tabular_structured': [
                        "Strong gradient-boosting models (LightGBM/XGBoost/CatBoost)",
                        "Feature engineering: interactions, target encoding, missing-value handling",
                        "Stacking/blending ensembles of boosting models and neural nets"
                    ]
                }
            
            def analyze_competition_context(self, overview_text: str, data_text: str) -> dict:
                combined_text = (overview_text + "\n" + data_text).lower()
                detected_domains = {}
                strategies = []
                problem_type = "unknown"
                
                for domain, keywords in self.domain_keywords.items():
                    matches = [k for k in keywords if k in combined_text]
                    if matches:
                        confidence = min(len(matches)/len(keywords),1.0)
                        detected_domains[domain] = {'matches': matches, 'confidence': confidence}
                        strategies.extend(self.strategy_templates.get(domain, []))
                        if domain in ['nlp_text','image_cv']:
                            problem_type = 'classification'
                        elif domain=='time_series':
                            problem_type='regression'
                        elif domain=='tabular_structured':
                            problem_type='classification'
                
                strategies = list(dict.fromkeys(strategies))
                return {
                    'problem_type': problem_type,
                    'domains_detected': detected_domains,
                    'strategies': strategies
                }

        # -------------------------------
        # STREAMLIT UI: MANUAL COPY-PASTE OPTION
        # -------------------------------
        st.markdown("### 🏆 Project Analysis")

        st.markdown("""
        Enter the **Overview** and **Data Description** text from Platform to enable advanced insights.
        This avoids scraping and ensures full legality.
        """)

        overview_text = st.text_area("Overview", height=150)
        data_text = st.text_area("Data Section", height=150)

        if st.button("Analyze"):
            if overview_text or data_text:
                nlp_processor = AdvancedNLPProcessor()
                context_results = nlp_processor.analyze_competition_context(overview_text, data_text)

                st.subheader("Detected Problem Type")
                st.info(context_results['problem_type'])

                st.subheader("Detected Domains")
                for d, v in context_results['domains_detected'].items():
                    st.markdown(f"- {d} (confidence {v['confidence']:.0%}): {', '.join(v['matches'])}")

                st.subheader("Suggested Top-Performing Strategies")
                for strat in context_results['strategies']:
                    st.markdown(f"- {strat}")

                # Show unified algorithm recommendations
                st.subheader("Recommended Algorithms")
                # FIXED: Use enhanced system for consistency - direct call
                rec_sys = UnifiedRecommendationSystem()
                algorithm_result = rec_sys.recommend(context_results['problem_type'], dataset=None)
                # Use proper schema from UnifiedRecommendationSystem
                algorithms = {algo: "Enhanced algorithm" for algo in algorithm_result['recommended']}
                for name, model in algorithms.items():
                    st.markdown(f"- {name}: {model}")
            else:
                st.warning("⚠️ Please paste at least one of the sections (Overview or Data) for analysis.")

